pub fn base64_decode(s: &str) -> Option<Vec<u8>> {
    let bytes: Vec<u8> = s.bytes().collect();
    if bytes.len() % 4 != 0 {
        return None;
    }
    let mut out = Vec::new();
    let n = bytes.len();
    for (ci, chunk) in bytes.chunks(4).enumerate() {
        let last = ci * 4 + 4 == n;
        let mut vals = [0u32; 4];
        let mut pad = 0;
        for (i, &c) in chunk.iter().enumerate() {
            if c == b'=' {
                if !last || i < 2 {
                    return None;
                }
                pad += 1;
                vals[i] = 0;
