        out.push((num >> 16) as u8);
        if pad < 2 {
            out.push((num >> 8) as u8);
        }
        if pad < 1 {
            out.push(num as u8);
        }
    }
    Some(out)
}

/// Parses a file size with an optional unit suffix (k, kb, kib, m, ...).
pub fn parse_filesize(s: &str) -> Option<u64> {
    let lower = s.trim().to_lowercase();
    let units: [(&str, u64); 10] = [
        ("kib", 1024),
        ("mib", 1024 * 1024),
        ("gib", 1024 * 1024 * 1024),
        ("kb", 1000),
        ("mb", 1000 * 1000),
        ("gb", 1000 * 1000 * 1000),
        ("k", 1024),
        ("m", 1024 * 1024),
        ("g", 1024 * 1024 * 1024),
        ("b", 1),
    ];
    for (suffix, mult) in units.iter() {
        if let Some(num) = lower.strip_suffix(suffix) {
            let num = num.trim();
            if num.is_empty() || !num.chars().next().unwrap().is_ascii_digit() {
                return None;
            }
            if let Ok(f) = num.parse::<f64>() {
                if f < 0.0 {
                    return None;
                }
                return Some((f * (*mult as f64)) as u64);
            }
            return None;
        }
    }
    None
}

/// Converts a string to f64 the way arithmetic operations do.
pub fn str_to_f64(s: &str) -> f64 {
    let t = s.trim();
    if let Ok(f) = t.parse::<f64>() {
        return f;
    }
    if let Some(v) = parse_filesize(t) {
        return v as f64;
    }
    0.0
}

pub fn str_to_f64_opt(s: &str) -> Option<f64> {
    let t = s.trim();
    if let Ok(f) = t.parse::<f64>() {
        return Some(f);
    }
    if let Some(v) = parse_filesize(t) {
        return Some(v as f64);
    }
    None
}

pub fn str_to_i64(s: &str) -> i64 {
