    if let Ok(i) = t.parse::<i64>() {
        return i;
    }
    if let Ok(f) = t.parse::<f64>() {
        return f as i64;
    }
    if let Some(v) = parse_filesize(t) {
        return v as i64;
    }
    0
}

pub fn str_to_bool(s: &str) -> bool {
    matches!(s.to_lowercase().as_str(), "true" | "1" | "yes" | "y" | "on")
}

pub fn format_f64(f: f64) -> String {
    format!("{}", f)
}

pub fn regex_escape_char(c: char, out: &mut String) {
    if "\\.+*?()|[]{}^$#&-~".contains(c) {
        out.push('\\');
    }
    out.push(c);
}

/// Converts a glob-like pattern to a case-insensitive anchored regex.
pub fn glob_to_regex(pattern: &str) -> String {
    let mut s = String::from("(?i)^");
    for c in pattern.chars() {
        match c {
            '*' => s.push_str(".*"),
            '?' => s.push('.'),
            _ => regex_escape_char(c, &mut s),
        }
    }
    s.push('$');
    s
}

pub fn is_glob(pattern: &str) -> bool {
    pattern.contains('*') || pattern.contains('?')
}

/// Converts an SQL LIKE pattern to a case-insensitive anchored regex.
pub fn like_to_regex(pattern: &str) -> String {
    let mut s = String::from("(?i)^");
    for c in pattern.chars() {
        match c {
            '%' => s.push_str(".*"),
            '_' => s.push('.'),
            _ => regex_escape_char(c, &mut s),
        }
    }
    s.push('$');
    s
}

pub struct SizeFormat {
    pub decimals: Option<usize>,
    pub space: bool,
    pub decimal: bool,
    pub conventional: bool,
    pub short: bool,
    pub fixed: Option<(u32, bool)>, // exponent, decimal units
}

pub fn parse_size_format(fmt: &str) -> Option<SizeFormat> {
    let mut f = SizeFormat { decimals: None, space: false, decimal: false, conventional: false, short: false, fixed: None };
    let mut rest = fmt;
    if let Some(r) = fmt.strip_prefix("%.") {
        let digits: String = r.chars().take_while(|c| c.is_ascii_digit()).collect();
        if !digits.is_empty() {
            f.decimals = digits.parse::<usize>().ok();
        }
        rest = &r[digits.len()..];
    }
    if rest.starts_with(' ') {
        f.space = true;
    }
    let lower: Vec<char> = rest.to_lowercase().chars().collect();
    let mut i = 0;
    while i < lower.len() {
        let c = lower[i];
        match c {
            ' ' | '%' | '.' | '0'..='9' => {
                i += 1;
            }
            'd' => {
                f.decimal = true;
                i += 1;
            }
            'c' => {
                f.conventional = true;
                i += 1;
            }
            's' => {
                f.short = true;
                i += 1;
            }
            'b' => {
                if f.fixed.is_some() {
                    return None;
                }
                f.fixed = Some((0, false));
                i += 1;
            }
            'k' | 'm' | 'g' | 't' | 'p' | 'e' => {
                if f.fixed.is_some() {
                    return None;
                }
                let exp = match c {
                    'k' => 1,
                    'm' => 2,
                    'g' => 3,
                    't' => 4,
                    'p' => 5,
                    _ => 6,
                };
                i += 1;
                if i + 1 < lower.len() + 1 && i < lower.len() && lower[i] == 'i' && i + 1 < lower.len() && lower[i + 1] == 'b' {
                    f.fixed = Some((exp, false));
                    i += 2;
                } else if i < lower.len() && lower[i] == 'b' {
                    f.fixed = Some((exp, true));
                    i += 1;
                } else {
                    f.fixed = Some((exp, false));
                }
            }
            _ => return None,
        }
    }
    Some(f)
}

pub fn format_size(size: u64, fmt: &str) -> Option<String> {
    let f = parse_size_format(fmt)?;
    let mut decimal_kilo = f.decimal;
    let mut decimal_units = f.decimal || f.conventional;
    let mut exp_fixed: Option<u32> = None;
    if let Some((exp, dec)) = f.fixed {
        exp_fixed = Some(exp);
        if dec {
            decimal_kilo = true;
            decimal_units = true;
        }
    }
    let kilo: f64 = if decimal_kilo { 1000.0 } else { 1024.0 };
    let mut value = size as f64;
    let mut exp: u32 = 0;
    match exp_fixed {
        Some(e) => {
            for _ in 0..e {
                value /= kilo;
            }
            exp = e;
        }
        None => {
            while value >= kilo && exp < 6 {
                value /= kilo;
                exp += 1;
            }
        }
    }
    let unit = if f.short {
        ["B", "K", "M", "G", "T", "P", "E"][exp as usize]
    } else if decimal_units {
        ["B", "KB", "MB", "GB", "TB", "PB", "EB"][exp as usize]
    } else {
        ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"][exp as usize]
    };
    let space = if f.space { " " } else { "" };
    let num = if exp == 0 {
        format!("{}", value as u64)
    } else {
        let decimals = match f.decimals {
            Some(d) => d,
            None => {
                if exp_fixed.is_some() {
                    0
                } else {
                    2
                }
            }
        };
        if value.fract() == 0.0 {
            format!("{}", value as u64)
        } else {
            format!("{:.*}", decimals, value)
        }
    };
    Some(format!("{}{}{}", num, space, unit))
}

pub fn format_time(secs: u64) -> String {
    if secs == 0 {
        return "0\u{3bc}s".to_string();
    }
    let days = secs / 86400;
    let hours = (secs % 86400) / 3600;
    let mins = (secs % 3600) / 60;
    let s = secs % 60;
    let mut parts = vec![];
    if days > 0 {
        parts.push(format!("{}d", days));
    }
    if hours > 0 {
        parts.push(format!("{}h", hours));
    }
    if mins > 0 {
        parts.push(format!("{}m", mins));
    }
    if s > 0 {
        parts.push(format!("{}s", s));
    }
    parts.join(",")
}

pub fn mode_string(meta: &Metadata) -> String {
    let ft = meta.file_type();
    let mode = meta.permissions().mode();
    mode_string_from(mode, if ft.is_symlink() {
        'l'
    } else if ft.is_dir() {
        'd'
    } else if ft.is_fifo() {
        'p'
    } else if ft.is_socket() {
        's'
    } else if ft.is_char_device() {
        'c'
    } else if ft.is_block_device() {
        'b'
    } else {
        '-'
    })
}

pub fn mode_string_from(mode: u32, t: char) -> String {
    let mut s = String::new();
    s.push(t);
    let bit = |m: u32, c: char| if mode & m != 0 { c } else { '-' };
    s.push(bit(0o400, 'r'));
    s.push(bit(0o200, 'w'));
    s.push(match (mode & 0o100 != 0, mode & 0o4000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        _ => '-',
    });
    s.push(bit(0o040, 'r'));
    s.push(bit(0o020, 'w'));
    s.push(match (mode & 0o010 != 0, mode & 0o2000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        _ => '-',
    });
    s.push(bit(0o004, 'r'));
    s.push(bit(0o002, 'w'));
    s.push(match (mode & 0o001 != 0, mode & 0o1000 != 0) {
        (true, true) => 't',
        (false, true) => 'T',
        (true, false) => 'x',
        _ => '-',
    });
    s
