pub fn meta_mode(meta: &Metadata) -> u32 {
    meta.mode()
}

pub fn is_hiragana(c: char) -> bool {
    ('\u{3040}'..='\u{309f}').contains(&c)
}
pub fn is_katakana(c: char) -> bool {
    ('\u{30a0}'..='\u{30ff}').contains(&c) || ('\u{31f0}'..='\u{31ff}').contains(&c) || ('\u{ff66}'..='\u{ff9f}').contains(&c)
}
pub fn is_kana(c: char) -> bool {
    is_hiragana(c) || is_katakana(c)
}
pub fn is_kanji(c: char) -> bool {
    ('\u{4e00}'..='\u{9fff}').contains(&c) || ('\u{3400}'..='\u{4dbf}').contains(&c) || ('\u{f900}'..='\u{faff}').contains(&c)
        || ('\u{20000}'..='\u{2a6df}').contains(&c)
}
pub fn is_japanese(c: char) -> bool {
    is_kana(c) || is_kanji(c) || ('\u{3000}'..='\u{303f}').contains(&c) || ('\u{ff00}'..='\u{ffef}').contains(&c)
}
pub fn is_greek(c: char) -> bool {
    ('\u{0370}'..='\u{03ff}').contains(&c) || ('\u{1f00}'..='\u{1fff}').contains(&c)
}

pub fn has_extension(name: &str, exts: &[String]) -> bool {
    let lower = name.to_lowercase();
    exts.iter().any(|e| lower.ends_with(&e.to_lowercase()))
}
