pub fn base64_decode(s: &str) -> Option<Vec<u8>> {
    let bytes: Vec<u8> = s.bytes().collect();
    if bytes.len() % 4 != 0 {
        return None;
    }
    let mut out = Vec::new();
    let n = bytes.len();
    for (ci, chunk) in bytes.chunks(4).enumerate() {
        let last = ci * 4 + 4 == n;
        let mut vals = [0u32; 4];
        let mut pad = 0;
        for (i, &c) in chunk.iter().enumerate() {
            if c == b'=' {
                if !last || i < 2 {
                    return None;
                }
                pad += 1;
                vals[i] = 0;
            } else {
                if pad > 0 {
                    return None;
                }
                let v = B64.iter().position(|&x| x == c)? as u32;
                vals[i] = v;
            }
        }
        let num = (vals[0] << 18) | (vals[1] << 12) | (vals[2] << 6) | vals[3];
        out.push((num >> 16) as u8);
        if pad < 2 {
            out.push((num >> 8) as u8);
        }
        if pad < 1 {
            out.push(num as u8);
        }
    }
    Some(out)
}

/// Parses a file size with an optional unit suffix (k, kb, kib, m, ...).
pub fn parse_filesize(s: &str) -> Option<u64> {
    let lower = s.trim().to_lowercase();
    let units: [(&str, u64); 10] = [
        ("kib", 1024),
        ("mib", 1024 * 1024),
        ("gib", 1024 * 1024 * 1024),
        ("kb", 1000),
        ("mb", 1000 * 1000),
        ("gb", 1000 * 1000 * 1000),
        ("k", 1024),
        ("m", 1024 * 1024),
        ("g", 1024 * 1024 * 1024),
        ("b", 1),
    ];
    for (suffix, mult) in units.iter() {
        if let Some(num) = lower.strip_suffix(suffix) {
            let num = num.trim();
            if num.is_empty() || !num.chars().next().unwrap().is_ascii_digit() {
                return None;
            }
            if let Ok(f) = num.parse::<f64>() {
                if f < 0.0 {
                    return None;
                }
                return Some((f * (*mult as f64)) as u64);
            }
            return None;
        }
    }
    None
}

