fn parse_iso(t: &str) -> Option<(i64, i64)> {
    // YYYY-MM-DD[( |T)HH[:MM[:SS[.fff]]]]
    let bytes = t.as_bytes();
    if bytes.len() < 10 {
        return None;
    }
    let is_d = |i: usize| bytes.get(i).map(|b| b.is_ascii_digit()).unwrap_or(false);
    if !(is_d(0) && is_d(1) && is_d(2) && is_d(3) && bytes[4] == b'-' && is_d(5) && is_d(6) && bytes[7] == b'-' && is_d(8) && is_d(9)) {
        return None;
    }
    let year: i32 = t[0..4].parse().ok()?;
    let month: u32 = t[5..7].parse().ok()?;
    let day: u32 = t[8..10].parse().ok()?;
    let rest = &t[10..];
    if rest.is_empty() {
        let start = from_local(year, month, day, 0, 0, 0)?;
        let (y2, m2, d2) = civil_add_days(year, month, day, 1);
        let end = from_local(y2, m2, d2, 0, 0, 0)? - 1;
        return Some((start, end));
    }
    let sep = rest.as_bytes()[0];
    if sep != b' ' && sep != b'T' {
        return None;
    }
    let time = rest[1..].trim_start();
    let parts: Vec<&str> = time.split(':').collect();
    if parts.is_empty() || parts.len() > 3 {
        return None;
    }
    let num = |p: &str| -> Option<u32> {
        if p.is_empty() || p.len() > 2 || !p.chars().all(|c| c.is_ascii_digit()) {
            None
        } else {
            p.parse().ok()
        }
    };
    let hour = num(parts[0])?;
    if parts.len() == 1 {
        let start = from_local(year, month, day, hour, 0, 0)?;
        return Some((start, start + 3599));
    }
    let min = num(parts[1])?;
    if parts.len() == 2 {
        let start = from_local(year, month, day, hour, min, 0)?;
        return Some((start, start + 59));
    }
    let sec_part = parts[2];
    let sec_str = match sec_part.find('.') {
        Some(i) => {
            let frac = &sec_part[i + 1..];
            if frac.is_empty() || !frac.chars().all(|c| c.is_ascii_digit()) {
                return None;
            }
            &sec_part[..i]
        }
        None => sec_part,
    };
    let sec = num(sec_str)?;
    let start = from_local(year, month, day, hour, min, sec)?;
    Some((start, start))
}

