    let start = from_local(y, m, d, 0, 0, 0)?;
    let (y2, m2, d2) = civil_add_days(y, m, d, 1);
    let end = from_local(y2, m2, d2, 0, 0, 0)? - 1;
    Some((start, end))
}

fn parse_time_of_day(s: &str) -> Option<(u32, u32, u32)> {
    let lower = s.to_lowercase();
    let (body, pm, am) = if let Some(b) = lower.strip_suffix("pm") {
        (b.trim().to_string(), true, false)
    } else if let Some(b) = lower.strip_suffix("am") {
        (b.trim().to_string(), false, true)
    } else {
        (lower.clone(), false, false)
    };
    let parts: Vec<&str> = body.split(':').collect();
    if parts.len() < 2 && !(pm || am) {
        return None;
    }
    if parts.len() > 3 {
        return None;
    }
    let mut vals = vec![];
    for p in &parts {
        if p.is_empty() || p.len() > 2 || !p.chars().all(|c| c.is_ascii_digit()) {
            return None;
        }
        vals.push(p.parse::<u32>().ok()?);
    }
    let mut h = vals[0];
    let m = *vals.get(1).unwrap_or(&0);
    let sec = *vals.get(2).unwrap_or(&0);
    if pm && h < 12 {
        h += 12;
    }
    if am && h == 12 {
        h = 0;
    }
    if h > 23 || m > 59 || sec > 59 {
        return None;
    }
    Some((h, m, sec))
}

fn parse_english(t: &str, us_dates: bool) -> Option<(i64, i64)> {
    let lower = t.to_lowercase();
    let lower = lower.replace(',', " ");
    let words: Vec<&str> = lower.split_whitespace().collect();
    if words.is_empty() {
        return None;
    }
    let now_ts = now();
    let today = to_local(now_ts);

    // N units ago
    if words.len() == 3 && words[2] == "ago" {
        let n: i64 = words[0].parse().ok()?;
        let unit = words[1].trim_end_matches('s');
        let secs = match unit {
            "sec" | "second" | "s" => n,
            "min" | "minute" | "m" => n * 60,
            "hour" | "h" | "hr" => n * 3600,
            "day" | "d" => n * 86400,
            "week" | "w" => n * 7 * 86400,
            "month" => return month_offset(now_ts, -n),
            "year" | "y" => return month_offset(now_ts, -n * 12),
            _ => return None,
        };
        let ts = now_ts - secs;
        return Some((ts, ts));
    }
    // N units (in the future)
    if words.len() == 2 {
        if let Ok(n) = words[0].parse::<i64>() {
            let unit = words[1].trim_end_matches('s');
            let secs = match unit {
                "sec" | "second" => Some(n),
                "min" | "minute" => Some(n * 60),
                "hour" => Some(n * 3600),
                "day" => Some(n * 86400),
                "week" => Some(n * 7 * 86400),
                _ => None,
            };
            if let Some(secs) = secs {
                let ts = now_ts + secs;
                return Some((ts, ts));
            }
        }
    }

    // split off a trailing time of day
    let mut date_words: Vec<&str> = words.clone();
    let mut tod: Option<(u32, u32, u32)> = None;
    if let Some(last) = date_words.last() {
        if let Some(tt) = parse_time_of_day(last) {
            tod = Some(tt);
            date_words.pop();
        }
    }

    let date: Option<(i32, u32, u32)> = if date_words.is_empty() {
        if tod.is_some() {
            Some((today.year, today.month, today.day))
        } else {
            None
        }
    } else {
        parse_english_date(&date_words, &today, us_dates, tod.is_some())
    };
    let (y, m, d) = date?;
    match tod {
        Some((h, mi, s)) => {
            let ts = from_local(y, m, d, h, mi, s)?;
            Some((ts, ts))
        }
        None => {
            if date_words.len() == 1 && date_words[0] == "now" {
                return Some((now_ts, now_ts));
            }
            day_interval(y, m, d)
        }
    }
}

fn month_offset(ts: i64, months: i64) -> Option<(i64, i64)> {
    let l = to_local(ts);
    let total = l.year as i64 * 12 + (l.month as i64 - 1) + months;
    let y = total.div_euclid(12) as i32;
    let m = (total.rem_euclid(12) + 1) as u32;
    let d = l.day.min(days_in_month(y, m));
    let t = from_local(y, m, d, l.hour, l.min, l.sec)?;
    Some((t, t))
}

fn parse_english_date(words: &[&str], today: &Local, us_dates: bool, has_time: bool) -> Option<(i32, u32, u32)> {
    let w0 = words[0];
    if words.len() == 1 {
        match w0 {
            "today" | "now" => return Some((today.year, today.month, today.day)),
            "yesterday" => return Some(civil_add_days(today.year, today.month, today.day, -1)),
            "tomorrow" => return Some(civil_add_days(today.year, today.month, today.day, 1)),
            _ => {}
        }
        if let Some(wd) = weekday_from_name(w0, has_time) {
            let diff = (wd as i64 - today.wday as i64).rem_euclid(7);
            let diff = if diff == 0 { 7 } else { diff };
            return Some(civil_add_days(today.year, today.month, today.day, diff));
        }
        // dd/mm[/yy[yy]]
        if w0.contains('/') {
            let parts: Vec<&str> = w0.split('/').collect();
            if parts.len() < 2 || parts.len() > 3 {
                return None;
            }
            let mut nums = vec![];
            for p in &parts {
                if p.is_empty() || !p.chars().all(|c| c.is_ascii_digit()) {
                    return None;
                }
                nums.push(p.parse::<i64>().ok()?);
            }
            let (d, m) = if us_dates { (nums[1], nums[0]) } else { (nums[0], nums[1]) };
            let y = if nums.len() == 3 {
                let y = nums[2];
                if parts[2].len() <= 2 {
                    2000 + y
                } else {
                    y
                }
            } else {
                today.year as i64
            };
            let (d, m, y) = (d as u32, m as u32, y as i32);
            if m < 1 || m > 12 || d < 1 || d > days_in_month(y, m) {
                return None;
            }
            return Some((y, m, d));
        }
        return None;
    }
    if words.len() == 2 {
        if w0 == "last" || w0 == "next" {
            let wd = weekday_from_name(words[1], true)?;
            if w0 == "last" {
                let diff = (today.wday as i64 - wd as i64).rem_euclid(7);
                return Some(civil_add_days(today.year, today.month, today.day, -diff));
            } else {
                let diff = (wd as i64 - today.wday as i64).rem_euclid(7);
                return Some(civil_add_days(today.year, today.month, today.day, diff + 7));
            }
        }
        // "apr 1" / "1 apr"
        if let (Some(m), Ok(d)) = (month_from_name(w0), words[1].parse::<u32>()) {
            if d >= 1 && d <= days_in_month(today.year, m) {
                return Some((today.year, m, d));
            }
            return None;
        }
        if let (Ok(d), Some(m)) = (w0.parse::<u32>(), month_from_name(words[1])) {
            if d >= 1 && d <= days_in_month(today.year, m) {
                return Some((today.year, m, d));
            }
            return None;
        }
        return None;
    }
    if words.len() == 3 {
        // "1 apr 2020", "april 1 2026" (with comma removed)
        if let (Ok(d), Some(m), Ok(y)) = (w0.parse::<u32>(), month_from_name(words[1]), words[2].parse::<i32>()) {
            if d >= 1 && d <= days_in_month(y, m) {
                return Some((y, m, d));
            }
            return None;
        }
        if let (Some(m), Ok(d), Ok(y)) = (month_from_name(w0), words[1].parse::<u32>(), words[2].parse::<i32>()) {
            if d >= 1 && d <= days_in_month(y, m) && words[2].len() == 4 {
                return Some((y, m, d));
            }
            return None;
        }
    }
    None
}
