//! Date/time helpers built on libc's localtime_r/mktime.

use std::os::raw::{c_char, c_int, c_long};

#[repr(C)]
#[derive(Clone, Copy)]
struct Tm {
    tm_sec: c_int,
    tm_min: c_int,
    tm_hour: c_int,
    tm_mday: c_int,
    tm_mon: c_int,
    tm_year: c_int,
    tm_wday: c_int,
    tm_yday: c_int,
    tm_isdst: c_int,
    tm_gmtoff: c_long,
    tm_zone: *const c_char,
}

extern "C" {
    fn localtime_r(t: *const i64, tm: *mut Tm) -> *mut Tm;
    fn mktime(tm: *mut Tm) -> i64;
    fn tzset();
}

pub fn init() {
    unsafe { tzset() }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct Local {
    pub year: i32,
    pub month: u32, // 1..12
    pub day: u32,
    pub hour: u32,
    pub min: u32,
    pub sec: u32,
    pub wday: u32, // 0 = Sunday
    pub yday: u32, // 0-based
}

fn empty_tm() -> Tm {
    Tm {
        tm_sec: 0,
        tm_min: 0,
        tm_hour: 0,
        tm_mday: 0,
        tm_mon: 0,
        tm_year: 0,
        tm_wday: 0,
        tm_yday: 0,
        tm_isdst: -1,
        tm_gmtoff: 0,
        tm_zone: std::ptr::null(),
    }
}

pub fn to_local(ts: i64) -> Local {
    let mut tm = empty_tm();
    unsafe {
        localtime_r(&ts, &mut tm);
    }
    Local {
        year: tm.tm_year + 1900,
        month: (tm.tm_mon + 1) as u32,
        day: tm.tm_mday as u32,
        hour: tm.tm_hour as u32,
        min: tm.tm_min as u32,
        sec: tm.tm_sec as u32,
        wday: tm.tm_wday as u32,
        yday: tm.tm_yday as u32,
    }
}

pub fn from_local(year: i32, month: u32, day: u32, hour: u32, min: u32, sec: u32) -> Option<i64> {
    if month < 1 || month > 12 || day < 1 || day > days_in_month(year, month) || hour > 23 || min > 59 || sec > 60 {
        return None;
    }
    let mut tm = empty_tm();
    tm.tm_year = year - 1900;
    tm.tm_mon = month as c_int - 1;
    tm.tm_mday = day as c_int;
    tm.tm_hour = hour as c_int;
    tm.tm_min = min as c_int;
    tm.tm_sec = sec as c_int;
    tm.tm_isdst = -1;
    let t = unsafe { mktime(&mut tm) };
    Some(t)
}

pub fn is_leap(year: i32) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

pub fn days_in_month(year: i32, month: u32) -> u32 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap(year) {
                29
            } else {
                28
            }
        }
        _ => 0,
    }
}

pub fn now() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

pub fn format_ts(ts: i64) -> String {
    let l = to_local(ts);
    format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", l.year, l.month, l.day, l.hour, l.min, l.sec)
}

pub fn format_date(ts: i64) -> String {
    let l = to_local(ts);
    format!("{:04}-{:02}-{:02}", l.year, l.month, l.day)
}

pub fn format_time(ts: i64) -> String {
    let l = to_local(ts);
    format!("{:02}:{:02}:{:02}", l.hour, l.min, l.sec)
}

pub fn day_start(ts: i64) -> i64 {
    let l = to_local(ts);
    from_local(l.year, l.month, l.day, 0, 0, 0).unwrap_or(ts)
}

/// Adds `days` calendar days keeping local wall-clock time.
pub fn add_days(ts: i64, days: i64) -> i64 {
    let l = to_local(ts);
    let (y, m, d) = civil_add_days(l.year, l.month, l.day, days);
    from_local(y, m, d, l.hour, l.min, l.sec).unwrap_or(ts + days * 86400)
}

fn days_from_civil(y: i32, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y as i64 - 1 } else { y as i64 };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let m = m as i64;
    let doy = (153 * (if m > 2 { m - 3 } else { m + 9 }) + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn civil_from_days(z: i64) -> (i32, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let y = if m <= 2 { y + 1 } else { y };
    (y as i32, m, d)
}

pub fn civil_add_days(y: i32, m: u32, d: u32, days: i64) -> (i32, u32, u32) {
    civil_from_days(days_from_civil(y, m, d) + days)
}

pub fn days_between(a: i64, b: i64) -> i64 {
    let la = to_local(a);
    let lb = to_local(b);
    days_from_civil(la.year, la.month, la.day) - days_from_civil(lb.year, lb.month, lb.day)
}

pub fn weekday_name(wday: u32) -> &'static str {
    ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"][wday as usize % 7]
}

fn month_from_name(s: &str) -> Option<u32> {
    let s = s.to_lowercase();
    let names = [
        "january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november",
        "december",
    ];
    for (i, n) in names.iter().enumerate() {
        if s.len() >= 3 && n.starts_with(&s) {
            return Some(i as u32 + 1);
        }
    }
    if s == "sept" {
        return Some(9);
    }
    None
}

fn weekday_from_name(s: &str, allow_abbrev: bool) -> Option<u32> {
    let s = s.to_lowercase();
    let names = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
    for (i, n) in names.iter().enumerate() {
        if s == *n {
            return Some(i as u32);
        }
        if allow_abbrev && s.len() >= 3 && n.starts_with(&s) {
            return Some(i as u32);
        }
    }
    None
}

/// Parses a datetime specification into an interval [start, end] (inclusive, seconds).
pub fn parse_datetime(s: &str, us_dates: bool) -> Result<(i64, i64), String> {
    let err = || format!("Can't parse datetime: {}", s);
    let t = s.trim();
    if t.is_empty() {
        return Err(err());
    }
    // relative days: -N / +N
    if let Ok(n) = t.parse::<i64>() {
        if t.starts_with('-') || t.starts_with('+') {
            let start = add_days(day_start(now()), n);
            let end = add_days(start, 1) - 1;
            return Ok((start, end));
        }
        return Err(err());
    }
    if let Some(r) = parse_iso(t) {
        return Ok(r);
    }
    if let Some(r) = parse_english(t, us_dates) {
        return Ok(r);
    }
    Err(err())
}

fn parse_iso(t: &str) -> Option<(i64, i64)> {
    // YYYY-MM-DD[( |T)HH[:MM[:SS[.fff]]]]
    let bytes = t.as_bytes();
    if bytes.len() < 10 {
        return None;
    }
    let is_d = |i: usize| bytes.get(i).map(|b| b.is_ascii_digit()).unwrap_or(false);
    if !(is_d(0) && is_d(1) && is_d(2) && is_d(3) && bytes[4] == b'-' && is_d(5) && is_d(6) && bytes[7] == b'-' && is_d(8) && is_d(9)) {
        return None;
    }
    let year: i32 = t[0..4].parse().ok()?;
    let month: u32 = t[5..7].parse().ok()?;
    let day: u32 = t[8..10].parse().ok()?;
    let rest = &t[10..];
    if rest.is_empty() {
        let start = from_local(year, month, day, 0, 0, 0)?;
        let (y2, m2, d2) = civil_add_days(year, month, day, 1);
        let end = from_local(y2, m2, d2, 0, 0, 0)? - 1;
        return Some((start, end));
    }
    let sep = rest.as_bytes()[0];
    if sep != b' ' && sep != b'T' {
        return None;
    }
    let time = rest[1..].trim_start();
    let parts: Vec<&str> = time.split(':').collect();
    if parts.is_empty() || parts.len() > 3 {
        return None;
    }
    let num = |p: &str| -> Option<u32> {
        if p.is_empty() || p.len() > 2 || !p.chars().all(|c| c.is_ascii_digit()) {
            None
        } else {
            p.parse().ok()
        }
    };
    let hour = num(parts[0])?;
    if parts.len() == 1 {
        let start = from_local(year, month, day, hour, 0, 0)?;
        return Some((start, start + 3599));
    }
    let min = num(parts[1])?;
    if parts.len() == 2 {
        let start = from_local(year, month, day, hour, min, 0)?;
        return Some((start, start + 59));
    }
    let sec_part = parts[2];
    let sec_str = match sec_part.find('.') {
        Some(i) => {
            let frac = &sec_part[i + 1..];
            if frac.is_empty() || !frac.chars().all(|c| c.is_ascii_digit()) {
                return None;
            }
            &sec_part[..i]
        }
        None => sec_part,
    };
    let sec = num(sec_str)?;
    let start = from_local(year, month, day, hour, min, sec)?;
    Some((start, start))
}

fn day_interval(y: i32, m: u32, d: u32) -> Option<(i64, i64)> {
    let start = from_local(y, m, d, 0, 0, 0)?;
    let (y2, m2, d2) = civil_add_days(y, m, d, 1);
    let end = from_local(y2, m2, d2, 0, 0, 0)? - 1;
    Some((start, end))
}

fn parse_time_of_day(s: &str) -> Option<(u32, u32, u32)> {
    let lower = s.to_lowercase();
    let (body, pm, am) = if let Some(b) = lower.strip_suffix("pm") {
        (b.trim().to_string(), true, false)
    } else if let Some(b) = lower.strip_suffix("am") {
        (b.trim().to_string(), false, true)
    } else {
        (lower.clone(), false, false)
    };
    let parts: Vec<&str> = body.split(':').collect();
    if parts.len() < 2 && !(pm || am) {
        return None;
    }
    if parts.len() > 3 {
        return None;
    }
    let mut vals = vec![];
    for p in &parts {
        if p.is_empty() || p.len() > 2 || !p.chars().all(|c| c.is_ascii_digit()) {
            return None;
        }
        vals.push(p.parse::<u32>().ok()?);
    }
    let mut h = vals[0];
    let m = *vals.get(1).unwrap_or(&0);
    let sec = *vals.get(2).unwrap_or(&0);
    if pm && h < 12 {
        h += 12;
    }
    if am && h == 12 {
        h = 0;
    }
    if h > 23 || m > 59 || sec > 59 {
        return None;
    }
    Some((h, m, sec))
}

fn parse_english(t: &str, us_dates: bool) -> Option<(i64, i64)> {
    let lower = t.to_lowercase();
    let lower = lower.replace(',', " ");
    let words: Vec<&str> = lower.split_whitespace().collect();
    if words.is_empty() {
        return None;
    }
    let now_ts = now();
    let today = to_local(now_ts);

    // N units ago
    if words.len() == 3 && words[2] == "ago" {
        let n: i64 = words[0].parse().ok()?;
        let unit = words[1].trim_end_matches('s');
        let secs = match unit {
            "sec" | "second" | "s" => n,
            "min" | "minute" | "m" => n * 60,
            "hour" | "h" | "hr" => n * 3600,
            "day" | "d" => n * 86400,
            "week" | "w" => n * 7 * 86400,
            "month" => return month_offset(now_ts, -n),
            "year" | "y" => return month_offset(now_ts, -n * 12),
            _ => return None,
        };
        let ts = now_ts - secs;
        return Some((ts, ts));
    }
    // N units (in the future)
    if words.len() == 2 {
        if let Ok(n) = words[0].parse::<i64>() {
            let unit = words[1].trim_end_matches('s');
            let secs = match unit {
                "sec" | "second" => Some(n),
                "min" | "minute" => Some(n * 60),
                "hour" => Some(n * 3600),
                "day" => Some(n * 86400),
                "week" => Some(n * 7 * 86400),
                _ => None,
            };
            if let Some(secs) = secs {
                let ts = now_ts + secs;
                return Some((ts, ts));
            }
        }
    }

    // split off a trailing time of day
    let mut date_words: Vec<&str> = words.clone();
    let mut tod: Option<(u32, u32, u32)> = None;
    if let Some(last) = date_words.last() {
        if let Some(tt) = parse_time_of_day(last) {
            tod = Some(tt);
            date_words.pop();
        }
    }

    let date: Option<(i32, u32, u32)> = if date_words.is_empty() {
        if tod.is_some() {
            Some((today.year, today.month, today.day))
        } else {
            None
        }
    } else {
        parse_english_date(&date_words, &today, us_dates, tod.is_some())
    };
    let (y, m, d) = date?;
    match tod {
        Some((h, mi, s)) => {
            let ts = from_local(y, m, d, h, mi, s)?;
            Some((ts, ts))
        }
        None => {
            if date_words.len() == 1 && date_words[0] == "now" {
                return Some((now_ts, now_ts));
            }
            day_interval(y, m, d)
        }
    }
}

fn month_offset(ts: i64, months: i64) -> Option<(i64, i64)> {
    let l = to_local(ts);
    let total = l.year as i64 * 12 + (l.month as i64 - 1) + months;
    let y = total.div_euclid(12) as i32;
    let m = (total.rem_euclid(12) + 1) as u32;
    let d = l.day.min(days_in_month(y, m));
    let t = from_local(y, m, d, l.hour, l.min, l.sec)?;
    Some((t, t))
}

fn parse_english_date(words: &[&str], today: &Local, us_dates: bool, has_time: bool) -> Option<(i32, u32, u32)> {
    let w0 = words[0];
    if words.len() == 1 {
        match w0 {
            "today" | "now" => return Some((today.year, today.month, today.day)),
            "yesterday" => return Some(civil_add_days(today.year, today.month, today.day, -1)),
            "tomorrow" => return Some(civil_add_days(today.year, today.month, today.day, 1)),
            _ => {}
        }
        if let Some(wd) = weekday_from_name(w0, has_time) {
            let diff = (wd as i64 - today.wday as i64).rem_euclid(7);
            let diff = if diff == 0 { 7 } else { diff };
            return Some(civil_add_days(today.year, today.month, today.day, diff));
        }
        // dd/mm[/yy[yy]]
        if w0.contains('/') {
            let parts: Vec<&str> = w0.split('/').collect();
            if parts.len() < 2 || parts.len() > 3 {
                return None;
            }
            let mut nums = vec![];
            for p in &parts {
                if p.is_empty() || !p.chars().all(|c| c.is_ascii_digit()) {
                    return None;
                }
                nums.push(p.parse::<i64>().ok()?);
            }
            let (d, m) = if us_dates { (nums[1], nums[0]) } else { (nums[0], nums[1]) };
            let y = if nums.len() == 3 {
                let y = nums[2];
                if parts[2].len() <= 2 {
                    2000 + y
                } else {
                    y
                }
            } else {
                today.year as i64
            };
            let (d, m, y) = (d as u32, m as u32, y as i32);
            if m < 1 || m > 12 || d < 1 || d > days_in_month(y, m) {
                return None;
            }
            return Some((y, m, d));
        }
        return None;
    }
    if words.len() == 2 {
        if w0 == "last" || w0 == "next" {
            let wd = weekday_from_name(words[1], true)?;
            if w0 == "last" {
                let diff = (today.wday as i64 - wd as i64).rem_euclid(7);
                return Some(civil_add_days(today.year, today.month, today.day, -diff));
            } else {
                let diff = (wd as i64 - today.wday as i64).rem_euclid(7);
                return Some(civil_add_days(today.year, today.month, today.day, diff + 7));
            }
        }
        // "apr 1" / "1 apr"
        if let (Some(m), Ok(d)) = (month_from_name(w0), words[1].parse::<u32>()) {
            if d >= 1 && d <= days_in_month(today.year, m) {
                return Some((today.year, m, d));
            }
            return None;
        }
        if let (Ok(d), Some(m)) = (w0.parse::<u32>(), month_from_name(words[1])) {
            if d >= 1 && d <= days_in_month(today.year, m) {
                return Some((today.year, m, d));
            }
            return None;
        }
        return None;
    }
    if words.len() == 3 {
        // "1 apr 2020", "april 1 2026" (with comma removed)
        if let (Ok(d), Some(m), Ok(y)) = (w0.parse::<u32>(), month_from_name(words[1]), words[2].parse::<i32>()) {
            if d >= 1 && d <= days_in_month(y, m) {
                return Some((y, m, d));
            }
            return None;
        }
        if let (Some(m), Ok(d), Ok(y)) = (month_from_name(w0), words[1].parse::<u32>(), words[2].parse::<i32>()) {
            if d >= 1 && d <= days_in_month(y, m) && words[2].len() == 4 {
                return Some((y, m, d));
            }
            return None;
        }
    }
    None
}
EOF
