            if self.at_eof() {
                self.skip_pending = false;
                break;
            }
            if self.at_arg_end() {
                self.advance_arg();
                continue;
            }
            // skip one char
            self.pos += 1;
            if self.at_arg_end() {
                // the skipped char was the last of this argument: keep skipping into the next one
                self.advance_arg();
                if self.at_eof() {
                    self.skip_pending = false;
                }
            } else {
                self.skip_pending = false;
            }
        }
    }

    fn prev_is_value(&self) -> bool {
        matches!(
            self.prev,
            Some(Lexeme::RawString(_)) | Some(Lexeme::String(_)) | Some(Lexeme::Close) | Some(Lexeme::CurlyClose)
        )
    }

    fn should_split(&self, s: &str) -> bool {
        match self.ctx {
            Ctx::Roots => false,
            Ctx::Fields => {
                Field::parse(s).is_some() || Function::parse(s).is_some() || is_numeric_like(s) || is_alias_field(s)
            }
            Ctx::Where => Field::parse(s).is_some() || is_alias_field(s),
        }
    }

    pub fn next_lexeme(&mut self) -> Option<Lexeme> {
        let l = self.next_inner();
        if let Some(ref lx) = l {
            if let Lexeme::RawString(s) = lx {
                let lower = s.to_lowercase();
                let after_sep = matches!(self.prev, Some(Lexeme::Comma) | Some(Lexeme::Open) | Some(Lexeme::CurlyOpen));
                if !after_sep {
                    if lower == "from" {
                        self.ctx = Ctx::Roots;
                    } else if lower == "where" {
                        self.ctx = Ctx::Where;
                    } else if self.ctx == Ctx::Roots
                        && matches!(lower.as_str(), "order" | "group" | "limit" | "offset" | "into")
                    {
                        self.ctx = Ctx::Where;
                    }
                }
            }
            self.prev = Some(lx.clone());
        }
        l
    }

    fn next_inner(&mut self) -> Option<Lexeme> {
        self.apply_skip();
        // skip whitespace and argument boundaries
        loop {
            if self.at_eof() {
                return None;
            }
            if self.at_arg_end() {
                self.advance_arg();
                continue;
            }
            let c = self.cur().unwrap();
            if c.is_whitespace() {
                self.pos += 1;
                continue;
            }
            break;
        }
        let c = self.cur().unwrap();
        match c {
            '\'' | '"' | '`' => {
                let quote = c;
                self.pos += 1;
                let mut s = String::new();
                loop {
                    if self.at_eof() {
                        // unterminated string: no lexeme
                        return None;
                    }
                    if self.at_arg_end() {
                        self.advance_arg();
                        continue;
                    }
                    let ch = self.cur().unwrap();
                    self.pos += 1;
                    if ch == quote {
                        if self.at_arg_end() && self.arg + 1 < self.args.len() {
                            self.advance_arg();
                            self.skip_pending = true;
                        }
                        break;
                    }
                    s.push(ch);
                }
                Some(Lexeme::String(s))
            }
            ',' => {
                self.pos += 1;
                Some(Lexeme::Comma)
            }
            '(' => {
                self.pos += 1;
                Some(Lexeme::Open)
            }
            ')' => {
                self.pos += 1;
                Some(Lexeme::Close)
            }
            '{' => {
                self.pos += 1;
                Some(Lexeme::CurlyOpen)
            }
            '}' => {
                self.pos += 1;
                Some(Lexeme::CurlyClose)
            }
            _ if is_op_char(c) => {
                let mut s = String::new();
                while let Some(ch) = self.cur() {
                    if is_op_char(ch) {
                        s.push(ch);
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                Some(Lexeme::Operator(s))
            }
            _ if is_arith_char(c)
                && (self.ctx == Ctx::Fields || (self.ctx == Ctx::Where && self.prev_is_value())) =>
            {
                self.pos += 1;
                Some(Lexeme::ArithmeticOperator(c.to_string()))
            }
            _ => {
                let mut s = String::new();
                while let Some(ch) = self.cur() {
                    if ch.is_whitespace() || matches!(ch, ',' | '(' | ')' | '{' | '}' | '\'' | '"' | '`') || is_op_char(ch) {
                        break;
                    }
                    if is_arith_char(ch) && !s.is_empty() && self.should_split(&s) {
                        break;
                    }
                    s.push(ch);
                    self.pos += 1;
                }
                Some(Lexeme::RawString(s))
            }
        }
    }
}

fn is_alias_field(s: &str) -> bool {
    if let Some(idx) = s.find('.') {
        let (a, f) = (&s[..idx], &s[idx + 1..]);
        !a.is_empty() && Field::parse(f).is_some()
    } else {
        false
    }
}
