    Or(Box<Expr>, Box<Expr>),
    Not(Box<Expr>),
}

#[derive(Clone, Debug)]
pub struct Expr {
    pub kind: ExprKind,
    pub minus: bool,
}

impl Expr {
    pub fn new(kind: ExprKind) -> Expr {
        Expr { kind, minus: false }
    }

    pub fn field(f: Field) -> Expr {
