    pub fn has_field(&self) -> bool {
        match &self.kind {
            ExprKind::Field(_) | ExprKind::AliasField(_, _) => true,
            ExprKind::Function(_, args) => args.iter().any(|a| a.has_field()),
            ExprKind::Value(_) => false,
            ExprKind::Arith(l, _, r) | ExprKind::Cmp(l, _, r) | ExprKind::And(l, r) | ExprKind::Or(l, r) => {
