            }
            ExprKind::Between(a, b, c, _) => a.has_field() || b.has_field() || c.has_field(),
            ExprKind::InList(a, l, _) => a.has_field() || l.iter().any(|x| x.has_field()),
            ExprKind::InQuery(a, _, _) => a.has_field(),
