use crate::expr::{ArithOp, Expr, ExprKind, Op};
use crate::field::Field;
use crate::function::Function;
use crate::lexer::Lexeme;
use crate::query::{OutputFormat, Query, Root, Traversal};
use std::rc::Rc;

pub struct Parser {
    lexemes: Vec<Lexeme>,
    idx: usize,
}

const EXPECTING: &str = "Error parsing expression, expecting string";

fn raw_lower(l: &Lexeme) -> Option<String> {
    match l {
        Lexeme::RawString(s) => Some(s.to_lowercase()),
        _ => None,
    }
}

impl Parser {
    pub fn new(lexemes: Vec<Lexeme>) -> Parser {
        Parser { lexemes, idx: 0 }
    }

    fn peek(&self) -> Option<&Lexeme> {
        self.lexemes.get(self.idx)
    }

    fn next(&mut self) -> Option<Lexeme> {
        let l = self.lexemes.get(self.idx).cloned();
        if l.is_some() {
            self.idx += 1;
        }
        l
    }

    fn back(&mut self) {
        if self.idx > 0 {
            self.idx -= 1;
        }
    }

    fn peek_word(&self) -> Option<String> {
        self.peek().and_then(raw_lower)
    }

    fn at_end(&self) -> bool {
        self.idx >= self.lexemes.len()
    }

    pub fn parse(&mut self, raw: &str) -> Result<Query, String> {
        let q = self.parse_query(raw, false)?;
        if !self.at_end() {
            return Err("could not parse tokens at the end of the query".to_string());
        }
        Ok(q)
    }

    fn parse_query(&mut self, raw: &str, sub: bool) -> Result<Query, String> {
        if self.peek_word().as_deref() == Some("select") {
            self.next();
        }
        let fields = self.parse_fields()?;
        if fields.is_empty() {
            if !self.at_end() && !(sub && matches!(self.peek(), Some(Lexeme::Close))) {
                return Err("could not parse tokens at the end of the query".to_string());
            }
            return Err("Error parsing fields, no selector found".to_string());
        }
        let mut roots_parsed = false;
        let mut roots = vec![];
        if self.peek_word().as_deref() == Some("from") {
            self.next();
            roots = self.parse_roots()?;
            roots_parsed = true;
        }
        let mut expr = None;
        if self.peek_word().as_deref() == Some("where") {
            self.next();
            expr = self.parse_or()?;
        }
        let mut grouping = vec![];
        if self.peek_word().as_deref() == Some("group") {
            self.next();
            if self.peek_word().as_deref() == Some("by") {
                self.next();
                grouping = self.parse_group_by()?;
            }
        }
        let mut ordering = vec![];
        let mut ordering_asc = vec![];
        if self.peek_word().as_deref() == Some("order") {
            self.next();
            if self.peek_word().as_deref() == Some("by") {
                self.next();
                let (o, a) = self.parse_order_by(&fields)?;
                ordering = o;
                ordering_asc = a;
            }
        }
        let mut limit = 0;
        let mut explicit_limit = false;
        if self.peek_word().as_deref() == Some("limit") {
            self.next();
            match self.next() {
                None => return Err("Error parsing limit, limit value not found".to_string()),
                Some(Lexeme::RawString(s)) => match s.parse::<usize>() {
                    Ok(n) => {
                        limit = n;
                        explicit_limit = true;
                    }
                    Err(_) => self.back(),
                },
                Some(_) => self.back(),
            }
        }
        let mut offset = 0;
        if self.peek_word().as_deref() == Some("offset") {
            self.next();
            match self.next() {
                None => return Err("Error parsing offset, offset value not found".to_string()),
                Some(Lexeme::RawString(s)) => match s.parse::<usize>() {
                    Ok(n) => offset = n,
                    Err(_) => return Err("Error parsing offset".to_string()),
                },
                Some(_) => return Err("Error parsing offset".to_string()),
            }
        }
        let mut output = OutputFormat::Tabs;
        if self.peek_word().as_deref() == Some("into") {
            self.next();
            match self.next() {
                Some(Lexeme::RawString(s)) | Some(Lexeme::String(s)) => {
                    output = match s.to_lowercase().as_str() {
                        "tabs" => OutputFormat::Tabs,
                        "lines" => OutputFormat::Lines,
                        "list" => OutputFormat::List,
                        "csv" => OutputFormat::Csv,
                        "json" => OutputFormat::Json,
                        "html" => OutputFormat::Html,
                        _ => return Err("Unknown output format".to_string()),
                    }
                }
                _ => return Err("Error parsing output format".to_string()),
            }
        }
        if !roots_parsed && self.peek_word().as_deref() == Some("from") {
            self.next();
            roots = self.parse_roots()?;
        }
        if roots.is_empty() {
            roots.push(Root::new("."));
        }
        if !explicit_limit && !fields.iter().any(|f| f.has_field()) {
            limit = 1;
        }
        Ok(Query {
            fields,
            roots,
            expr,
            grouping,
            ordering,
            ordering_asc,
            limit,
            explicit_limit,
            offset,
            output,
            raw: raw.to_string(),
        })
    }

    fn parse_fields(&mut self) -> Result<Vec<Expr>, String> {
        let mut fields = vec![];
        let mut after_comma = false;
        loop {
            match self.peek().cloned() {
                None => break,
                Some(Lexeme::Comma) => {
                    self.next();
                    after_comma = true;
                    continue;
                }
                Some(Lexeme::RawString(s)) => {
                    let l = s.to_lowercase();
                    if l == "select" || l == "as" {
                        break;
                    }
                    if !after_comma
                        && matches!(
                            l.as_str(),
                            "from" | "where" | "order" | "by" | "group" | "limit" | "offset" | "into"
                        )
                    {
                        break;
                    }
                }
                Some(Lexeme::ArithmeticOperator(op)) if op == "*" => {
                    self.next();
                    for f in [Field::Mode, Field::User, Field::Group, Field::Size, Field::Modified, Field::Path] {
                        fields.push(Expr::field(f));
                    }
                    after_comma = false;
                    continue;
                }
                _ => {}
            }
            let save = self.idx;
            match self.parse_field_expr()? {
                Some(e) => fields.push(e),
                None => {
                    self.idx = save;
                    break;
                }
            }
            after_comma = false;
        }
        Ok(fields)
    }

    fn parse_field_expr(&mut self) -> Result<Option<Expr>, String> {
        let left = match self.parse_add_sub(false)? {
            Some(l) => l,
            None => return Ok(None),
        };
        if let Some(Lexeme::Operator(op)) = self.peek().cloned() {
            if let Some(o) = Op::from_symbol(&op) {
                let save = self.idx;
                self.next();
                match self.parse_add_sub(false)? {
                    Some(r) => return Ok(Some(Expr::new(ExprKind::Cmp(Box::new(left), o, Box::new(r))))),
                    None => {
                        self.idx = save;
                        return Ok(Some(left));
                    }
                }
            } else {
                return Err(format!("Unknown operator: {}", op));
            }
        }
        Ok(Some(left))
    }

    fn parse_roots(&mut self) -> Result<Vec<Root>, String> {
        let mut roots = vec![];
        loop {
            match self.peek().cloned() {
                Some(Lexeme::Comma) => {
                    self.next();
                    continue;
                }
                Some(Lexeme::RawString(s)) | Some(Lexeme::String(s)) => {
                    if let Some(Lexeme::RawString(_)) = self.peek() {
                        let l = s.to_lowercase();
                        if matches!(l.as_str(), "where" | "order" | "group" | "limit" | "offset" | "into") {
                            break;
                        }
                    }
                    self.next();
                    let mut root = Root::new(&s);
                    self.parse_root_options(&mut root)?;
                    roots.push(root);
                }
                _ => break,
            }
        }
        Ok(roots)
    }

    fn parse_root_options(&mut self, root: &mut Root) -> Result<(), String> {
        loop {
            let w = match self.peek_word() {
                Some(w) => w,
                None => break,
            };
            match w.as_str() {
                "mindepth" | "maxdepth" | "depth" => {
                    self.next();
                    match self.next() {
                        None => return Err("Error parsing root options".to_string()),
                        Some(Lexeme::RawString(n)) => match n.parse::<u32>() {
                            Ok(v) => {
                                if w == "mindepth" {
                                    root.min_depth = v;
                                } else {
                                    root.max_depth = v;
                                }
                            }
                            Err(_) => {
                                self.back();
                                break;
                            }
                        },
                        Some(_) => {
                            self.back();
                            break;
                        }
                    }
                }
                "symlinks" | "sym" => {
                    self.next();
                    root.symlinks = true;
                }
                "archives" | "arc" => {
                    self.next();
                    root.archives = true;
                }
                "gitignore" | "git" => {
                    self.next();
                    root.gitignore = Some(true);
                }
                "nogitignore" | "nogit" => {
                    self.next();
                    root.gitignore = Some(false);
                }
                "hgignore" | "hg" => {
                    self.next();
                    root.hgignore = Some(true);
                }
                "nohgignore" | "nohg" => {
                    self.next();
                    root.hgignore = Some(false);
                }
                "dockerignore" | "docker" | "dock" => {
                    self.next();
                    root.dockerignore = Some(true);
                }
                "nodockerignore" | "nodocker" | "nodock" => {
                    self.next();
                    root.dockerignore = Some(false);
                }
                "dfs" => {
                    self.next();
                    root.traversal = Traversal::Dfs;
                }
                "bfs" => {
                    self.next();
                    root.traversal = Traversal::Bfs;
                }
                "regexp" => {
                    self.next();
                    root.regexp = true;
                }
                "as" => {
                    self.next();
                    match self.next() {
                        Some(Lexeme::RawString(a)) | Some(Lexeme::String(a)) => root.alias = Some(a),
                        None => return Err("Error parsing root options".to_string()),
                        Some(_) => {
                            self.back();
                            return Err("Error parsing root options".to_string());
                        }
                    }
                }
                _ => break,
            }
        }
        Ok(())
    }

    fn parse_group_by(&mut self) -> Result<Vec<Expr>, String> {
        let mut v = vec![];
        loop {
            match self.peek().cloned() {
                Some(Lexeme::Comma) => {
                    self.next();
                    continue;
                }
                Some(Lexeme::RawString(s)) => {
                    let l = s.to_lowercase();
                    if matches!(l.as_str(), "order" | "limit" | "offset" | "into" | "from" | "having") {
                        break;
                    }
                }
                None => break,
                _ => {}
            }
            let save = self.idx;
            match self.parse_add_sub(false)? {
                Some(e) => v.push(e),
                None => {
                    self.idx = save;
                    break;
                }
            }
        }
        Ok(v)
    }

    fn parse_order_by(&mut self, fields: &[Expr]) -> Result<(Vec<Expr>, Vec<bool>), String> {
        let mut v = vec![];
        let mut asc = vec![];
        loop {
            match self.peek().cloned() {
                Some(Lexeme::Comma) => {
                    self.next();
                    continue;
                }
                Some(Lexeme::RawString(s)) => {
                    let l = s.to_lowercase();
                    if l == "desc" {
                        self.next();
                        if let Some(last) = asc.last_mut() {
                            *last = false;
                        }
                        continue;
                    }
                    if l == "asc" {
                        self.next();
                        if let Some(last) = asc.last_mut() {
                            *last = true;
                        }
                        continue;
                    }
                    if matches!(l.as_str(), "limit" | "offset" | "into" | "from") {
                        break;
                    }
                    if let Ok(n) = s.parse::<usize>() {
                        self.next();
                        if n == 0 || n > fields.len() {
                            return Err("Order by field index is out of range".to_string());
                        }
                        v.push(fields[n - 1].clone());
                        asc.push(true);
                        continue;
                    }
                }
                None => break,
                _ => {}
            }
            let save = self.idx;
            match self.parse_add_sub(false)? {
                Some(e) => {
                    v.push(e);
                    asc.push(true);
                }
                None => {
                    self.idx = save;
                    break;
                }
            }
        }
        Ok((v, asc))
    }

    // ---------- expressions ----------

    fn parse_or(&mut self) -> Result<Option<Expr>, String> {
        let mut left = match self.parse_and()? {
            Some(l) => l,
            None => return Ok(None),
        };
        while self.peek_word().as_deref() == Some("or") {
            self.next();
            match self.parse_and()? {
                Some(r) => left = Expr::new(ExprKind::Or(Box::new(left), Box::new(r))),
                None => {
                    if self.at_end() {
                        return Err(EXPECTING.to_string());
                    }
                    self.back();
                    break;
                }
            }
        }
        Ok(Some(left))
    }

    fn parse_and(&mut self) -> Result<Option<Expr>, String> {
        let mut left = match self.parse_not()? {
            Some(l) => l,
            None => return Ok(None),
        };
        while self.peek_word().as_deref() == Some("and") {
            self.next();
            match self.parse_not()? {
                Some(r) => left = Expr::new(ExprKind::And(Box::new(left), Box::new(r))),
                None => {
                    if self.at_end() {
                        return Err(EXPECTING.to_string());
                    }
                    self.back();
                    break;
                }
            }
        }
        Ok(Some(left))
    }

    fn parse_not(&mut self) -> Result<Option<Expr>, String> {
        if self.peek_word().as_deref() == Some("not") {
            self.next();
            if self.at_end() {
                return Err(EXPECTING.to_string());
            }
            return match self.parse_not()? {
                Some(e) => Ok(Some(Expr::new(ExprKind::Not(Box::new(e))))),
                None => {
                    self.back();
                    Ok(None)
                }
            };
        }
        self.parse_cond()
    }

    fn parse_subquery(&mut self) -> Result<Query, String> {
        let start = self.idx;
        let q = self.parse_query("", true)?;
        let _ = start;
        Ok(q)
    }

    fn parse_cond(&mut self) -> Result<Option<Expr>, String> {
        if self.at_end() {
            return Err(EXPECTING.to_string());
        }
        if self.peek_word().as_deref() == Some("exists") {
            self.next();
            match self.peek() {
                Some(Lexeme::Open) | Some(Lexeme::CurlyOpen) => {
                    self.next();
                    let q = self.parse_subquery()?;
                    match self.next() {
                        Some(Lexeme::Close) | Some(Lexeme::CurlyClose) => {}
                        _ => return Err("Unmatched parenthesis".to_string()),
                    }
                    return Ok(Some(Expr::new(ExprKind::Exists(Rc::new(q), false))));
                }
                _ => {
                    self.back();
                    return Ok(None);
                }
            }
        }
        // parenthesized logical expression
        if let Some(Lexeme::Open) | Some(Lexeme::CurlyOpen) = self.peek() {
            let save = self.idx;
            self.next();
            let inner = self.parse_or();
            if let Ok(Some(e)) = inner {
                if let Some(Lexeme::Close) | Some(Lexeme::CurlyClose) = self.peek() {
                    self.next();
                    let followed_by_op = match self.peek() {
                        Some(Lexeme::Operator(_)) | Some(Lexeme::ArithmeticOperator(_)) => true,
                        Some(Lexeme::RawString(s)) => {
                            let l = s.to_lowercase();
                            Op::from_word(&l).is_some()
                                || matches!(l.as_str(), "between" | "in" | "plus" | "minus" | "mul" | "div" | "mod")
                                || (l == "not" && {
                                    let nl = self.lexemes.get(self.idx + 1).and_then(raw_lower);
                                    matches!(nl.as_deref(), Some("between") | Some("in") | Some("like"))
                                        || nl.as_deref().map(|x| Op::from_word(x).is_some()).unwrap_or(false)
                                })
                        }
                        _ => false,
                    };
                    let is_logical = matches!(e.kind, ExprKind::And(..) | ExprKind::Or(..) | ExprKind::Not(..) | ExprKind::Cmp(..) | ExprKind::Between(..) | ExprKind::InList(..) | ExprKind::InQuery(..) | ExprKind::Exists(..));
                    if !followed_by_op || is_logical {
                        return Ok(Some(e));
                    }
                } else {
                    return Err("Unmatched parenthesis".to_string());
                }
            } else if let Err(e) = inner {
                return Err(e);
            }
            self.idx = save;
        }
        let left = match self.parse_add_sub(true)? {
            Some(l) => l,
            None => return Ok(None),
        };
        let mut negate = false;
        if self.peek_word().as_deref() == Some("not") {
            self.next();
            negate = true;
        }
        let tok = self.peek().cloned();
        let op: Option<Op> = match &tok {
            Some(Lexeme::Operator(s)) => match Op::from_symbol(s) {
                Some(o) => Some(o),
                None => return Err(format!("Unknown operator: {}", s)),
            },
            Some(Lexeme::RawString(s)) => {
                let l = s.to_lowercase();
                if l == "between" {
                    self.next();
                    let lo = self.parse_add_sub(true)?.ok_or_else(|| "Error parsing BETWEEN operator".to_string())?;
                    if self.peek_word().as_deref() != Some("and") {
                        return Err("Error parsing BETWEEN operator".to_string());
                    }
                    self.next();
                    let hi = match self.parse_add_sub(true)? {
                        Some(h) => h,
                        None => return Err("Error parsing BETWEEN operator".to_string()),
                    };
                    return Ok(Some(Expr::new(ExprKind::Between(Box::new(left), Box::new(lo), Box::new(hi), negate))));
                }
                if l == "in" {
                    self.next();
                    match self.peek() {
                        Some(Lexeme::Open) | Some(Lexeme::CurlyOpen) => {
                            self.next();
                        }
                        _ => {
                            self.back();
                            if negate {
                                self.back();
                            }
                            return Ok(Some(left));
                        }
                    }
                    if self.peek_word().as_deref() == Some("select") {
                        let q = self.parse_subquery()?;
                        match self.next() {
                            Some(Lexeme::Close) | Some(Lexeme::CurlyClose) => {}
                            _ => return Err("Unmatched parenthesis".to_string()),
                        }
                        return Ok(Some(Expr::new(ExprKind::InQuery(Box::new(left), Rc::new(q), negate))));
                    }
                    let mut list = vec![];
                    loop {
                        match self.peek() {
                            Some(Lexeme::Close) | Some(Lexeme::CurlyClose) => {
                                self.next();
                                break;
                            }
                            Some(Lexeme::Comma) => {
                                self.next();
                            }
                            None => return Err("Unmatched parenthesis".to_string()),
                            _ => match self.parse_add_sub(true)? {
                                Some(e) => list.push(e),
                                None => return Err("Unmatched parenthesis".to_string()),
                            },
                        }
                    }
                    return Ok(Some(Expr::new(ExprKind::InList(Box::new(left), list, negate))));
                }
                Op::from_word(&l)
            }
            _ => None,
        };
        let op = match op {
            Some(o) => o,
            None => {
                if negate {
                    self.back();
                }
                return Ok(Some(left));
            }
        };
        self.next();
        let right = match self.parse_add_sub(true)? {
            Some(r) => r,
            None => {
                if self.at_end() {
                    return Err(EXPECTING.to_string());
                }
                return Err(EXPECTING.to_string());
            }
        };
        let op = if negate { op.negate() } else { op };
        Ok(Some(Expr::new(ExprKind::Cmp(Box::new(left), op, Box::new(right)))))
    }

    fn arith_op(&self, l: &Lexeme, add: bool) -> Option<ArithOp> {
        match l {
            Lexeme::ArithmeticOperator(s) => match s.as_str() {
                "+" if add => Some(ArithOp::Add),
                "-" if add => Some(ArithOp::Subtract),
                "*" if !add => Some(ArithOp::Multiply),
                "/" if !add => Some(ArithOp::Divide),
                "%" if !add => Some(ArithOp::Modulo),
                _ => None,
            },
            Lexeme::RawString(s) => match s.to_lowercase().as_str() {
                "plus" if add => Some(ArithOp::Add),
                "minus" if add => Some(ArithOp::Subtract),
                "mul" if !add => Some(ArithOp::Multiply),
                "div" if !add => Some(ArithOp::Divide),
                "mod" if !add => Some(ArithOp::Modulo),
                _ => None,
            },
            _ => None,
        }
    }

    fn parse_add_sub(&mut self, wh: bool) -> Result<Option<Expr>, String> {
        let mut left = match self.parse_mul_div(wh)? {
            Some(l) => l,
            None => return Ok(None),
        };
        loop {
            let op = match self.peek().and_then(|l| self.arith_op(l, true)) {
                Some(op) => op,
                None => break,
            };
            let save = self.idx;
            self.next();
            match self.parse_mul_div(wh)? {
                Some(r) => left = Expr::new(ExprKind::Arith(Box::new(left), op, Box::new(r))),
                None => {
                    self.idx = save;
                    break;
                }
            }
        }
        Ok(Some(left))
    }

    fn parse_mul_div(&mut self, wh: bool) -> Result<Option<Expr>, String> {
        let mut left = match self.parse_unary(wh)? {
            Some(l) => l,
            None => return Ok(None),
        };
        loop {
            let op = match self.peek().and_then(|l| self.arith_op(l, false)) {
                Some(op) => op,
                None => break,
            };
            let save = self.idx;
            self.next();
            match self.parse_unary(wh)? {
                Some(r) => left = Expr::new(ExprKind::Arith(Box::new(left), op, Box::new(r))),
                None => {
                    self.idx = save;
                    break;
                }
            }
        }
        Ok(Some(left))
    }

    fn parse_unary(&mut self, wh: bool) -> Result<Option<Expr>, String> {
        let mut minus = false;
        let mut signed = false;
        if let Some(Lexeme::ArithmeticOperator(s)) = self.peek().cloned() {
            if s == "-" || s == "+" {
                minus = s == "-";
                signed = true;
                self.next();
                match self.peek() {
                    Some(Lexeme::RawString(_)) | Some(Lexeme::String(_)) => {}
                    None => {
                        if wh {
                            return Err(EXPECTING.to_string());
                        }
                        self.back();
                        return Ok(None);
                    }
                    _ => {
                        self.back();
                        return Ok(None);
                    }
                }
            }
        }
        let e = self.parse_primary(wh)?;
        match e {
            Some(mut e) => {
                if minus {
                    if let ExprKind::Value(ref mut v) = e.kind {
                        *v = format!("-{}", v);
                    } else {
                        e.minus = true;
                    }
                }
                Ok(Some(e))
            }
            None => {
                if signed {
                    self.back();
                }
                Ok(None)
            }
        }
    }

    fn parse_primary(&mut self, wh: bool) -> Result<Option<Expr>, String> {
        let l = match self.next() {
            Some(l) => l,
            None => {
                if wh {
                    return Err(EXPECTING.to_string());
                }
                return Ok(None);
            }
        };
        match l {
            Lexeme::Open | Lexeme::CurlyOpen => {
                let inner = if wh { self.parse_or()? } else { self.parse_field_expr()? };
                match inner {
                    Some(e) => match self.next() {
                        Some(Lexeme::Close) | Some(Lexeme::CurlyClose) => Ok(Some(e)),
                        None => Err("Unmatched parenthesis".to_string()),
                        Some(_) => {
                            self.back();
                            Err("Unmatched parenthesis".to_string())
                        }
                    },
                    None => {
                        if self.at_end() {
                            return Err("Unmatched parenthesis".to_string());
                        }
                        Ok(None)
                    }
                }
            }
            Lexeme::String(s) => Ok(Some(Expr::value(&s))),
            Lexeme::Unterminated(s) => {
                if wh {
                    Err(format!("Unterminated quoted string: {}", s))
                } else {
                    self.back();
                    Ok(None)
                }
            }
            Lexeme::RawString(s) => {
                if let Some(f) = Field::parse(&s) {
                    return Ok(Some(Expr::field(f)));
                }
                if let Some(idx) = s.find('.') {
                    let (a, fname) = (&s[..idx], &s[idx + 1..]);
                    if !a.is_empty() {
                        if let Some(f) = Field::parse(fname) {
                            return Ok(Some(Expr::new(ExprKind::AliasField(a.to_string(), f))));
                        }
                    }
                }
                if let Some(func) = Function::parse(&s) {
                    if let Some(Lexeme::Open) | Some(Lexeme::CurlyOpen) = self.peek() {
                        self.next();
                        let mut args = vec![];
                        loop {
                            match self.peek().cloned() {
                                None => break,
                                Some(Lexeme::Close) | Some(Lexeme::CurlyClose) => {
                                    self.next();
                                    break;
                                }
                                Some(Lexeme::Comma) => {
                                    self.next();
                                }
                                Some(Lexeme::ArithmeticOperator(op)) if op == "*" => {
                                    self.next();
                                    args.push(Expr::value("*"));
                                }
                                _ => {
                                    let a = if wh { self.parse_add_sub(true)? } else { self.parse_field_expr()? };
                                    match a {
                                        Some(a) => args.push(a),
                                        None => {
                                            return Err("Unmatched parenthesis".to_string());
                                        }
                                    }
                                }
                            }
                        }
                        return Ok(Some(Expr::new(ExprKind::Function(func, args))));
                    }
                    return Ok(Some(Expr::new(ExprKind::Function(func, vec![]))));
                }
                Ok(Some(Expr::value(&s)))
            }
            _ => {
                self.back();
                Ok(None)
            }
        }
    }
}
