        s.push_str(&toml_list("is_archive", &self.is_archive));
        s.push_str(&toml_list("is_audio", &self.is_audio));
        s.push_str(&toml_list("is_book", &self.is_book));
        s.push_str(&toml_list("is_doc", &self.is_doc));
        s.push_str(&toml_list("is_font", &self.is_font));
        s.push_str(&toml_list("is_image", &self.is_image));
        s.push_str(&toml_list("is_source", &self.is_source));
        s.push_str(&toml_list("is_video", &self.is_video));
        s.push_str(&format!("default_file_size_format = \"{}\"\n", self.default_file_size_format));
        s.push_str(&format!("us_dates = {}\n", self.us_dates));
        s.push_str(&format!("check_for_updates = {}\n", self.check_for_updates));
        s
    }

    fn from_toml(text: &str) -> Result<Config, String> {
        let mut cfg = Config::default();
        let chars: Vec<char> = text.chars().collect();
        let mut i = 0;
        let n = chars.len();
        let skip_ws = |i: &mut usize, nl: bool| {
            while *i < n {
                let c = chars[*i];
                if c == ' ' || c == '\t' || c == '\r' || (nl && c == '\n') {
                    *i += 1;
                } else if c == '#' {
                    while *i < n && chars[*i] != '\n' {
                        *i += 1;
                    }
                } else {
                    break;
                }
            }
        };
        fn parse_string(chars: &[char], i: &mut usize) -> Result<String, String> {
            let q = chars[*i];
            *i += 1;
            let mut s = String::new();
            while *i < chars.len() && chars[*i] != q {
                if q == '"' && chars[*i] == '\\' && *i + 1 < chars.len() {
                    *i += 1;
                    match chars[*i] {
                        'n' => s.push('\n'),
                        't' => s.push('\t'),
                        c => s.push(c),
                    }
                } else {
                    s.push(chars[*i]);
                }
                *i += 1;
            }
            if *i >= chars.len() {
                return Err("invalid basic string".to_string());
            }
            *i += 1;
            Ok(s)
        }
        loop {
            skip_ws(&mut i, true);
            if i >= n {
                break;
            }
            let mut key = String::new();
            while i < n && (chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-') {
                key.push(chars[i]);
                i += 1;
            }
            if key.is_empty() {
                return Err("invalid key".to_string());
            }
            skip_ws(&mut i, false);
            if i >= n || chars[i] != '=' {
                return Err("expected `=`".to_string());
            }
            i += 1;
            skip_ws(&mut i, false);
            if i >= n {
                return Err("expected value".to_string());
            }
            enum Val {
                B(bool),
                S(String),
                L(Vec<String>),
                Other,
            }
            let val = if chars[i] == '"' || chars[i] == '\'' {
                Val::S(parse_string(&chars, &mut i)?)
            } else if chars[i] == '[' {
                i += 1;
                let mut list = vec![];
                loop {
                    skip_ws(&mut i, true);
                    if i >= n {
                        return Err("unclosed array, expected `]`".to_string());
                    }
                    if chars[i] == ']' {
                        i += 1;
                        break;
                    }
                    if chars[i] == '"' || chars[i] == '\'' {
                        list.push(parse_string(&chars, &mut i)?);
                    } else {
                        return Err("invalid array".to_string());
                    }
                    skip_ws(&mut i, true);
                    if i < n && chars[i] == ',' {
                        i += 1;
                    }
                }
                Val::L(list)
            } else {
                let mut w = String::new();
                while i < n && !chars[i].is_whitespace() && chars[i] != '#' {
                    w.push(chars[i]);
                    i += 1;
                }
                match w.as_str() {
                    "true" => Val::B(true),
                    "false" => Val::B(false),
                    _ => Val::Other,
                }
            };
            match (key.as_str(), val) {
                ("no_color", Val::B(b)) => cfg.no_color = b,
                ("gitignore", Val::B(b)) => cfg.gitignore = b,
                ("hgignore", Val::B(b)) => cfg.hgignore = b,
                ("dockerignore", Val::B(b)) => cfg.dockerignore = b,
                ("us_dates", Val::B(b)) => cfg.us_dates = b,
                ("check_for_updates", Val::B(b)) => cfg.check_for_updates = b,
                ("default_file_size_format", Val::S(s)) => cfg.default_file_size_format = s,
                ("is_zip_archive", Val::L(l)) => cfg.is_zip_archive = l,
                ("is_archive", Val::L(l)) => cfg.is_archive = l,
                ("is_audio", Val::L(l)) => cfg.is_audio = l,
                ("is_book", Val::L(l)) => cfg.is_book = l,
                ("is_doc", Val::L(l)) => cfg.is_doc = l,
                ("is_font", Val::L(l)) => cfg.is_font = l,
                ("is_image", Val::L(l)) => cfg.is_image = l,
                ("is_source", Val::L(l)) => cfg.is_source = l,
                ("is_video", Val::L(l)) => cfg.is_video = l,
                (
                    "no_color" | "gitignore" | "hgignore" | "dockerignore" | "us_dates" | "check_for_updates"
                    | "default_file_size_format" | "is_zip_archive" | "is_archive" | "is_audio" | "is_book"
                    | "is_doc" | "is_font" | "is_image" | "is_source" | "is_video",
                    _,
                ) => return Err("invalid type".to_string()),
                _ => {}
            }
        }
        Ok(cfg)
    }

    fn config_dir() -> Option<PathBuf> {
        if let Ok(x) = std::env::var("XDG_CONFIG_HOME") {
            if !x.is_empty() && x.starts_with('/') {
                return Some(PathBuf::from(x));
            }
        }
        let home = std::env::var("HOME").ok().filter(|h| !h.is_empty())?;
        Some(PathBuf::from(home).join(".config"))
    }

    pub fn load(custom: Option<&str>) -> Config {
        if let Some(path) = custom {
            return match fs::read_to_string(path) {
                Ok(text) => match Config::from_toml(&text) {
                    Ok(c) => c,
                    Err(e) => {
                        eprintln!("TOML parse error: {}", e);
                        Config::default()
                    }
                },
                Err(_) => {
                    eprintln!("Could not open config file. Using default settings.");
                    Config::default()
                }
            };
        }
        if let Some(dir) = Config::config_dir() {
            let file = dir.join("fselect").join("config.toml");
            if file.exists() {
                if let Ok(text) = fs::read_to_string(&file) {
                    return match Config::from_toml(&text) {
                        Ok(c) => c,
                        Err(e) => {
                            eprintln!("TOML parse error: {}", e);
                            Config::default()
                        }
                    };
                }
            } else {
                // try next to the executable
                if let Ok(exe) = std::env::current_exe() {
                    if let Some(parent) = exe.parent() {
                        let local = parent.join("config.toml");
                        if local.exists() {
                            if let Ok(text) = fs::read_to_string(&local) {
                                if let Ok(c) = Config::from_toml(&text) {
                                    return c;
                                }
                            }
                        }
                    }
                }
                let cfg = Config::default();
                if fs::create_dir_all(file.parent().unwrap()).is_ok() {
                    let _ = fs::write(&file, cfg.to_toml());
                }
                return cfg;
            }
        }
        Config::default()
    }
}
