//! A small content-based MIME type detector.

fn starts(data: &[u8], sig: &[u8]) -> bool {
    data.len() >= sig.len() && &data[..sig.len()] == sig
}

fn at(data: &[u8], off: usize, sig: &[u8]) -> bool {
    data.len() >= off + sig.len() && &data[off..off + sig.len()] == sig
}

fn find_in(data: &[u8], range: usize, sig: &[u8]) -> bool {
    let end = data.len().min(range + sig.len());
    if end < sig.len() {
        return false;
    }
    data[..end].windows(sig.len()).any(|w| w == sig)
}

fn shebang_mime(first_line: &str) -> Option<&'static str> {
    let l = first_line.trim_end();
    let rest = l.strip_prefix("#!")?.trim_start();
    let mut parts = rest.split_whitespace();
    let mut prog = parts.next().unwrap_or("");
    if prog.ends_with("/env") {
        prog = parts.next().unwrap_or("");
    }
    let base = prog.rsplit('/').next().unwrap_or(prog);
    match base {
        "sh" | "bash" | "zsh" | "dash" | "ksh" | "ash" => Some("application/x-shellscript"),
        "csh" | "tcsh" => Some("application/x-csh"),
        "perl" => Some("application/x-perl"),
        "python3" => Some("text/x-python3"),
        "python" | "python2" => Some("text/x-python"),
        "ruby" => Some("application/x-ruby"),
        "awk" | "gawk" | "nawk" | "mawk" => Some("application/x-awk"),
        "lua" => Some("text/x-lua"),
        "php" => Some("application/x-php"),
        _ => None,
    }
}

fn is_text_plain(data: &[u8]) -> bool {
    let n = data.len().min(4096);
    !data[..n].contains(&0)
}

pub fn detect(data: &[u8]) -> String {
    let m = detect_inner(data);
    m.to_string()
}

fn detect_inner(data: &[u8]) -> &'static str {
    if data.is_empty() {
        return "text/plain";
    }
    if starts(data, b"\x89PNG\r\n\x1a\n") {
        return "image/png";
    }
    if starts(data, b"\xff\xd8\xff") {
        return "image/jpeg";
    }
    if starts(data, b"GIF87a") || starts(data, b"GIF89a") {
        return "image/gif";
    }
    if starts(data, b"BM") && data.len() > 14 && matches!(data[14], 12 | 40 | 56 | 64 | 108 | 124) {
        return "image/bmp";
    }
    if starts(data, b"II*\x00") || starts(data, b"MM\x00*") {
        return "image/tiff";
    }
    if starts(data, b"\x00\x00\x01\x00") {
        return "image/vnd.microsoft.icon";
    }
    if starts(data, b"8BPS") {
        return "image/vnd.adobe.photoshop";
    }
    if find_in(data, 1024, b"%PDF-") {
        return "application/pdf";
    }
    if starts(data, b"PK\x03\x04") {
        return "application/zip";
    }
    if starts(data, b"\x1f\x8b") {
        return "application/gzip";
    }
    if starts(data, b"BZh") {
        return "application/x-bzip2";
    }
    if starts(data, b"\xfd7zXZ\x00") {
        return "application/x-xz";
    }
    if starts(data, b"7z\xbc\xaf\x27\x1c") {
        return "application/x-7z-compressed";
    }
    if starts(data, b"Rar!\x1a\x07") {
        return "application/vnd.rar";
    }
    if at(data, 257, b"ustar") {
        return "application/x-tar";
    }
    if starts(data, b"\x7fELF") {
        if data.len() > 17 {
            let et = if data.get(5) == Some(&2) { data[17] } else { data[16] };
            if et == 1 {
                return "application/x-object";
            }
            if et == 4 {
                return "application/x-core";
            }
        }
        return "application/x-executable";
    }
    if starts(data, b"SQLite format 3\x00") {
        return "application/vnd.sqlite3";
    }
    if starts(data, b"\xca\xfe\xba\xbe") {
        return "application/x-java";
    }
    if starts(data, b"ID3") {
        return "audio/mpeg";
    }
    if starts(data, b"OggS") {
        return "audio/ogg";
    }
    if starts(data, b"fLaC") {
        return "audio/flac";
    }
    if starts(data, b"RIFF") {
        if at(data, 8, b"WAVE") {
            return "audio/vnd.wave";
        }
        if at(data, 8, b"AVI ") {
            return "video/x-msvideo";
        }
        return "application/x-riff";
    }
    if at(data, 4, b"ftyp") {
        return "video/mp4";
    }
    if starts(data, b"\x1a\x45\xdf\xa3") {
        return "video/x-matroska";
    }
    if starts(data, b"{\\rtf") {
        return "application/rtf";
    }
    if starts(data, b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1") {
        return "application/x-ole-storage";
    }
    if starts(data, b"wOFF") {
        return "font/woff";
    }
    if starts(data, b"wOF2") {
        return "font/woff2";
    }
    if starts(data, b"OTTO") {
        return "font/otf";
    }
    if starts(data, b"\x00\x01\x00\x00\x00") {
        return "font/ttf";
    }
    if !is_text_plain(data) {
        if starts(data, b"\xff\xfb") || starts(data, b"\xff\xf3") || starts(data, b"\xff\xf2") {
            return "audio/mpeg";
        }
        return "application/octet-stream";
    }
    // text based
    let head_len = data.len().min(4096);
    let head = String::from_utf8_lossy(&data[..head_len]);
    let first_line = head.lines().next().unwrap_or("");
    if first_line.starts_with("#!") {
        if let Some(m) = shebang_mime(first_line) {
            return m;
        }
        return "text/plain";
    }
    let trimmed = head.trim_start();
    let lower = trimmed.to_lowercase();
    if lower.starts_with("<?xml") {
        if lower.contains("<svg") {
            return "image/svg+xml";
        }
        if lower.contains("<html") && lower.contains("xhtml") {
            return "application/xhtml+xml";
        }
        if lower.contains("<rss") {
            return "application/rss+xml";
        }
        if lower.contains("<feed") && lower.contains("atom") {
            return "application/atom+xml";
        }
        return "application/xml";
    }
    if lower.starts_with("<!doctype html") || lower.starts_with("<html") || lower.starts_with("<head") || lower.starts_with("<body") {
        return "text/html";
    }
    if starts(data, b"<?php") {
        return "application/x-php";
    }
    if starts(data, b"#include") {
        return "text/x-csrc";
    }
    if starts(data, b"%!PS") || starts(data, b"\\documentclass") || starts(data, b"\\input") {
        return "text/x-tex";
    }
    if starts(data, b"diff ") || starts(data, b"--- ") {
        return "text/x-patch";
    }
    if starts(data, b"From ") {
        return "application/mbox";
    }
    if starts(data, b"-----BEGIN CERTIFICATE-----") {
        return "application/pkix-cert+pem";
    }
    if starts(data, b"-----BEGIN PGP MESSAGE-----") {
        return "application/pgp-encrypted";
    }
    "text/plain"
}

pub fn is_text_mime(mime: &str) -> bool {
    if mime.starts_with("text/") {
        return true;
    }
    if mime.ends_with("+xml") {
        return true;
    }
    matches!(
        mime,
        "application/x-shellscript"
            | "application/x-perl"
            | "application/x-ruby"
            | "application/x-php"
            | "application/x-awk"
            | "application/javascript"
            | "application/json"
    )
}
EOF
echo ok"}

