pub fn image_dims(data: &[u8]) -> Option<(u64, u64)> {
    if data.len() >= 24 && &data[..8] == b"\x89PNG\r\n\x1a\n" {
        return Some((be32(data, 16)? as u64, be32(data, 20)? as u64));
    }
    if data.len() >= 10 && (&data[..6] == b"GIF87a" || &data[..6] == b"GIF89a") {
        return Some((le16(data, 6)? as u64, le16(data, 8)? as u64));
    }
    if data.len() >= 26 && &data[..2] == b"BM" {
        let hsize = le32(data, 14)?;
        if hsize == 12 {
            return Some((le16(data, 18)? as u64, le16(data, 20)? as u64));
        }
        let w = le32(data, 18)? as i32;
        let h = le32(data, 22)? as i32;
        return Some((w.unsigned_abs() as u64, h.unsigned_abs() as u64));
    }
    if data.len() >= 3 && &data[..3] == b"\xff\xd8\xff" {
        return jpeg_dims(data);
    }
    if data.len() >= 30 && &data[..4] == b"RIFF" && &data[8..12] == b"WEBP" {
        match &data[12..16] {
            b"VP8 " => {
                return Some(((le16(data, 26)? & 0x3fff) as u64, (le16(data, 28)? & 0x3fff) as u64));
            }
            b"VP8L" => {
                let b = &data[21..25];
                let w = 1 + (((b[1] as u32 & 0x3f) << 8) | b[0] as u32);
                let h = 1 + (((b[3] as u32 & 0xf) << 10) | ((b[2] as u32) << 2) | ((b[1] as u32 & 0xc0) >> 6));
                return Some((w as u64, h as u64));
            }
            b"VP8X" => {
                return Some(((le24(data, 24)? + 1) as u64, (le24(data, 27)? + 1) as u64));
            }
            _ => return None,
        }
    }
    if data.len() >= 26 && &data[..4] == b"8BPS" {
        return Some((be32(data, 18)? as u64, be32(data, 14)? as u64));
    }
    if data.len() >= 8 && (&data[..4] == b"II*\x00" || &data[..4] == b"MM\x00*") {
        return tiff_dims(data);
    }
    if data.len() >= 8 && &data[..4] == b"\x00\x00\x01\x00" {
        let w = if data[6] == 0 { 256 } else { data[6] as u64 };
        let h = if data[7] == 0 { 256 } else { data[7] as u64 };
        return Some((w, h));
    }
    None
}

fn jpeg_dims(data: &[u8]) -> Option<(u64, u64)> {
    let mut i = 2;
    while i + 4 <= data.len() {
        if data[i] != 0xff {
            i += 1;
            continue;
        }
        let marker = data[i + 1];
        if marker == 0xff {
            i += 1;
            continue;
        }
        if marker == 0xd8 || marker == 0x01 || (0xd0..=0xd7).contains(&marker) {
            i += 2;
            continue;
        }
        let len = be16(data, i + 2)? as usize;
        if (0xc0..=0xcf).contains(&marker) && marker != 0xc4 && marker != 0xc8 && marker != 0xcc {
            let h = be16(data, i + 5)?;
            let w = be16(data, i + 7)?;
            return Some((w as u64, h as u64));
        }
        i += 2 + len;
    }
    None
}

fn tiff_dims(data: &[u8]) -> Option<(u64, u64)> {
    let le = &data[..2] == b"II";
    let r16 = |o: usize| if le { le16(data, o) } else { be16(data, o) };
    let r32 = |o: usize| if le { le32(data, o) } else { be32(data, o) };
    let ifd = r32(4)? as usize;
    let n = r16(ifd)? as usize;
    let mut w = None;
    let mut h = None;
    for k in 0..n {
        let e = ifd + 2 + k * 12;
        let tag = r16(e)?;
        let typ = r16(e + 2)?;
        let val = if typ == 3 { r16(e + 8)? } else { r32(e + 8)? };
        if tag == 256 {
            w = Some(val as u64);
        } else if tag == 257 {
            h = Some(val as u64);
        }
    }
    Some((w?, h?))
}

fn parse_svg_len(s: &str) -> Option<u64> {
    let num: String = s.trim().chars().take_while(|c| c.is_ascii_digit() || *c == '.').collect();
    let f: f64 = num.parse().ok()?;
    Some(f as u64)
}

fn svg_attr(tag: &str, name: &str) -> Option<String> {
    let mut search = 0;
    while let Some(pos) = tag[search..].find(name) {
        let p = search + pos;
        let before_ok = p == 0 || tag.as_bytes()[p - 1].is_ascii_whitespace();
        let rest = &tag[p + name.len()..];
        let rest_trim = rest.trim_start();
        if before_ok && rest_trim.starts_with('=') {
            let r = rest_trim[1..].trim_start();
            let q = r.chars().next()?;
            if q == '"' || q == '\'' {
                let end = r[1..].find(q)?;
                return Some(r[1..1 + end].to_string());
            }
        }
        search = p + name.len();
    }
    None
}

pub fn svg_dims(data: &[u8]) -> Option<(u64, u64)> {
    let text = String::from_utf8_lossy(data);
    let start = text.find("<svg")?;
    let end = text[start..].find('>')? + start;
    let tag = &text[start + 4..end];
    let w = svg_attr(tag, "width").and_then(|v| parse_svg_len(&v));
    let h = svg_attr(tag, "height").and_then(|v| parse_svg_len(&v));
    match (w, h) {
        (Some(w), Some(h)) => Some((w, h)),
        _ => {
            let vb = svg_attr(tag, "viewBox")?;
            let parts: Vec<f64> = vb
                .split(|c: char| c.is_whitespace() || c == ',')
                .filter(|s| !s.is_empty())
                .filter_map(|s| s.parse().ok())
                .collect();
            if parts.len() == 4 {
                Some((parts[2] as u64, parts[3] as u64))
            } else {
                None
            }
        }
    }
}

pub fn mp4_dims(data: &[u8]) -> Option<(u64, u64)> {
    // search for a 'tkhd' box and read width/height (16.16 fixed)
    let pos = data.windows(4).position(|w| w == b"tkhd")?;
    let start = pos + 4;
    let version = *data.get(start)?;
    let off = if version == 1 { start + 4 + 8 + 8 + 4 + 4 + 8 } else { start + 4 + 4 + 4 + 4 + 4 + 4 };
    // reserved(8) layer(2) alt(2) volume(2) reserved(2) matrix(36)
    let off = off + 8 + 2 + 2 + 2 + 2 + 36;
    let w = be32(data, off)? >> 16;
    let h = be32(data, off + 4)? >> 16;
    if w == 0 && h == 0 {
        return None;
    }
    Some((w as u64, h as u64))
}

#[derive(Default, Clone, Debug)]
pub struct Mp3Info {
    pub title: Option<String>,
    pub artist: Option<String>,
    pub album: Option<String>,
    pub year: Option<i64>,
    pub genre: Option<String>,
    pub bitrate: Option<i64>,
    pub freq: Option<i64>,
    pub duration: Option<i64>,
}

const GENRES: &[&str] = &[
    "Blues", "ClassicRock", "Country", "Dance", "Disco", "Funk", "Grunge", "HipHop", "Jazz", "Metal", "NewAge",
    "Oldies", "Other", "Pop", "RAndB", "Rap", "Reggae", "Rock", "Techno", "Industrial", "Alternative", "Ska",
    "DeathMetal", "Pranks", "Soundtrack", "EuroTechno", "Ambient", "TripHop", "Vocal", "JazzFunk", "Fusion",
    "Trance", "Classical", "Instrumental", "Acid", "House", "Game", "SoundClip", "Gospel", "Noise", "AlternRock",
    "Bass", "Soul", "Punk", "Space", "Meditative", "InstrumentalPop", "InstrumentalRock", "Ethnic", "Gothic",
    "Darkwave", "TechnoIndustrial", "Electronic", "PopFolk", "Eurodance", "Dream", "SouthernRock", "Comedy",
    "Cult", "Gangsta", "Top40", "ChristianRap", "PopFunk", "Jungle", "NativeAmerican", "Cabaret", "NewWave",
    "Psychadelic", "Rave", "Showtunes", "Trailer", "LoFi", "Tribal", "AcidPunk", "AcidJazz", "Polka", "Retro",
    "Musical", "RockAndRoll", "HardRock",
];

fn latin1(b: &[u8]) -> String {
    b.iter().map(|&c| c as char).collect()
}

fn id3v1_str(b: &[u8]) -> Option<String> {
    let end = b.iter().position(|&c| c == 0).unwrap_or(b.len());
    let s = latin1(&b[..end]).trim_end().to_string();
    if s.is_empty() {
        None
    } else {
        Some(s)
    }
}

fn decode_id3_text(b: &[u8]) -> String {
    if b.is_empty() {
        return String::new();
    }
    let enc = b[0];
    let body = &b[1..];
    let s = match enc {
        0 => latin1(body),
        1 | 2 => {
            let (mut start, mut le) = (0, enc == 1);
            if body.len() >= 2 && body[0] == 0xff && body[1] == 0xfe {
                start = 2;
                le = true;
            } else if body.len() >= 2 && body[0] == 0xfe && body[1] == 0xff {
                start = 2;
                le = false;
            }
            if enc == 2 {
                le = false;
            }
            let units: Vec<u16> = body[start..]
                .chunks(2)
                .filter(|c| c.len() == 2)
                .map(|c| if le { u16::from_le_bytes([c[0], c[1]]) } else { u16::from_be_bytes([c[0], c[1]]) })
                .collect();
            String::from_utf16_lossy(&units)
        }
        _ => String::from_utf8_lossy(body).to_string(),
    };
    s.trim_end_matches('\0').to_string()
}

fn synchsafe(b: &[u8]) -> usize {
    ((b[0] as usize & 0x7f) << 21) | ((b[1] as usize & 0x7f) << 14) | ((b[2] as usize & 0x7f) << 7) | (b[3] as usize & 0x7f)
}

pub fn mp3_info(data: &[u8]) -> Option<Mp3Info> {
    let mut info = Mp3Info::default();
    let mut audio_start = 0;
    let mut found_tag = false;
    if data.len() >= 10 && &data[..3] == b"ID3" {
        let ver = data[3];
        let size = synchsafe(&data[6..10]);
        audio_start = 10 + size;
        found_tag = true;
        let end = (10 + size).min(data.len());
        let mut i = 10;
        while i + 10 <= end {
            let id = &data[i..i + 4];
            if id[0] == 0 {
                break;
            }
            let fsize = if ver >= 4 { synchsafe(&data[i + 4..i + 8]) } else { be32(data, i + 4)? as usize };
            let body_start = i + 10;
            let body_end = (body_start + fsize).min(end);
            let body = &data[body_start..body_end];
            let text = decode_id3_text(body);
            match id {
                b"TIT2" => info.title = Some(text),
                b"TPE1" => info.artist = Some(text),
                b"TALB" => info.album = Some(text),
                b"TYER" | b"TDRC" => info.year = text.get(0..4).and_then(|y| y.parse().ok()),
                b"TCON" => info.genre = Some(text),
                _ => {}
            }
            i = body_start + fsize;
        }
    }
    if data.len() >= 128 {
        let t = &data[data.len() - 128..];
        if &t[..3] == b"TAG" {
            found_tag = true;
            if info.title.is_none() {
                info.title = id3v1_str(&t[3..33]);
            }
            if info.artist.is_none() {
                info.artist = id3v1_str(&t[33..63]);
            }
            if info.album.is_none() {
                info.album = id3v1_str(&t[63..93]);
            }
            if info.year.is_none() {
                info.year = id3v1_str(&t[93..97]).and_then(|y| y.parse().ok());
            }
            if info.genre.is_none() {
                let g = t[127] as usize;
                if g < GENRES.len() {
                    info.genre = Some(GENRES[g].to_string());
                }
            }
        }
    }
    // find first frame
    let mut i = audio_start;
    let mut frames = 0u64;
    let mut total_secs = 0f64;
    while i + 4 <= data.len() {
        if data[i] == 0xff && (data[i + 1] & 0xe0) == 0xe0 {
            let h = &data[i..i + 4];
            let version = (h[1] >> 3) & 3; // 3 = MPEG1, 2 = MPEG2, 0 = MPEG2.5
            let layer = (h[1] >> 1) & 3; // 1 = layer III
            let br_idx = (h[2] >> 4) as usize;
            let sr_idx = ((h[2] >> 2) & 3) as usize;
            let padding = ((h[2] >> 1) & 1) as u64;
            if version == 1 || layer == 0 || br_idx == 0 || br_idx == 15 || sr_idx == 3 {
                i += 1;
                continue;
            }
            let br_table_v1_l3 = [0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320];
            let br_table_v1_l2 = [0, 32, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 384];
            let br_table_v1_l1 = [0, 32, 64, 96, 128, 160, 192, 224, 256, 288, 320, 352, 384, 416, 448];
            let br_table_v2_l1 = [0, 32, 48, 56, 64, 80, 96, 112, 128, 144, 160, 176, 192, 224, 256];
            let br_table_v2_l23 = [0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160];
            let bitrate = match (version, layer) {
                (3, 1) => br_table_v1_l3[br_idx],
                (3, 2) => br_table_v1_l2[br_idx],
                (3, 3) => br_table_v1_l1[br_idx],
                (_, 3) => br_table_v2_l1[br_idx],
                _ => br_table_v2_l23[br_idx],
            } as u64;
            let sr = match version {
                3 => [44100, 48000, 32000][sr_idx],
                2 => [22050, 24000, 16000][sr_idx],
                _ => [11025, 12000, 8000][sr_idx],
            } as u64;
            let samples: u64 = match (version, layer) {
                (_, 3) => 384,
                (3, _) => 1152,
                (_, 1) => 576,
                _ => 1152,
            };
            let frame_len = if layer == 3 {
                (12 * bitrate * 1000 / sr + padding) * 4
            } else {
                samples / 8 * bitrate * 1000 / sr + padding
            };
            if frames == 0 {
                info.bitrate = Some(bitrate as i64);
                info.freq = Some(sr as i64);
            }
            frames += 1;
            total_secs += samples as f64 / sr as f64;
            if frame_len == 0 {
                break;
            }
            i += frame_len as usize;
        } else {
            if frames > 0 {
                break;
            }
            i += 1;
        }
    }
    if frames > 0 {
        info.duration = Some(total_secs as i64);
    }
    if frames == 0 && !found_tag {
        return None;
    }
    Some(info)
}
