//! Minimal ZIP central-directory reader (no decompression).

#[derive(Clone, Debug)]
pub struct ZipEntry {
    pub name: String,
    pub size: u64,
    pub compressed: u64,
    pub dos_time: u16,
    pub dos_date: u16,
    pub mode: Option<u32>,
    pub is_dir: bool,
    pub crc: u32,
}

fn le16(d: &[u8], o: usize) -> Option<u16> {
    Some(u16::from_le_bytes([*d.get(o)?, *d.get(o + 1)?]))
}
fn le32(d: &[u8], o: usize) -> Option<u32> {
    Some(u32::from_le_bytes([*d.get(o)?, *d.get(o + 1)?, *d.get(o + 2)?, *d.get(o + 3)?]))
}

pub fn list(data: &[u8]) -> Option<Vec<ZipEntry>> {
    if data.len() < 22 {
        return None;
    }
    // locate end of central directory
    let min = data.len().saturating_sub(22 + 65535);
    let mut eocd = None;
    let mut i = data.len() - 22;
    loop {
        if &data[i..i + 4] == b"PK\x05\x06" {
            eocd = Some(i);
            break;
        }
        if i == min || i == 0 {
            break;
        }
        i -= 1;
    }
    let eocd = eocd?;
    let count = le16(data, eocd + 10)? as usize;
    let cd_off = le32(data, eocd + 16)? as usize;
    let mut entries = vec![];
    let mut p = cd_off;
    for _ in 0..count {
        if le32(data, p)? != 0x02014b50 {
            return None;
        }
        let made_by = le16(data, p + 4)?;
        let flags = le16(data, p + 8)?;
        let time = le16(data, p + 12)?;
        let date = le16(data, p + 14)?;
        let crc = le32(data, p + 16)?;
        let csize = le32(data, p + 20)? as u64;
        let usize_ = le32(data, p + 24)? as u64;
        let nlen = le16(data, p + 28)? as usize;
        let elen = le16(data, p + 30)? as usize;
        let clen = le16(data, p + 32)? as usize;
        let ext_attr = le32(data, p + 38)?;
        let name_bytes = data.get(p + 46..p + 46 + nlen)?;
        let name = if flags & 0x800 != 0 {
            String::from_utf8_lossy(name_bytes).to_string()
        } else {
            match std::str::from_utf8(name_bytes) {
                Ok(s) => s.to_string(),
                Err(_) => name_bytes.iter().map(|&b| b as char).collect(),
            }
        };
        let host = made_by >> 8;
        let mode = if host == 3 && (ext_attr >> 16) != 0 { Some(ext_attr >> 16) } else { None };
        let is_dir = name.ends_with('/');
        entries.push(ZipEntry { name, size: usize_, compressed: csize, dos_time: time, dos_date: date, mode, is_dir, crc });
        p += 46 + nlen + elen + clen;
    }
    Some(entries)
}

impl ZipEntry {
    pub fn datetime(&self) -> (i32, u32, u32, u32, u32, u32) {
        let d = self.dos_date as u32;
        let t = self.dos_time as u32;
        let year = 1980 + (d >> 9) as i32;
        let month = (d >> 5) & 0xf;
        let day = d & 0x1f;
        let hour = t >> 11;
        let min = (t >> 5) & 0x3f;
        let sec = (t & 0x1f) * 2;
        (year, month, day, hour, min, sec)
    }
}
