//! .gitignore / .hgignore / .dockerignore support.

use regex::Regex;
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

#[derive(Clone, Debug)]
struct GitPattern {
    regex: Regex,
    negated: bool,
    dir_only: bool,
}

fn glob_part_to_regex(p: &str, star_crosses: bool) -> String {
    let chars: Vec<char> = p.chars().collect();
    let mut s = String::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    // '**'
                    let at_start = i == 0 || chars[i - 1] == '/';
                    let followed_by_slash = i + 2 < chars.len() && chars[i + 2] == '/';
                    let at_end = i + 2 == chars.len();
                    if at_start && followed_by_slash {
                        s.push_str("(?:.*/)?");
                        i += 3;
                        continue;
                    }
                    if at_start && at_end {
                        s.push_str(".*");
                        i += 2;
                        continue;
                    }
                    s.push_str(if star_crosses { ".*" } else { "[^/]*" });
                    i += 2;
                    continue;
                }
                s.push_str(if star_crosses { ".*" } else { "[^/]*" });
            }
            '?' => s.push_str(if star_crosses { "." } else { "[^/]" }),
            '[' => {
                let mut j = i + 1;
                let mut class = String::from("[");
                if j < chars.len() && (chars[j] == '!' || chars[j] == '^') {
                    class.push('^');
                    j += 1;
                }
                let mut closed = false;
                let start = j;
                while j < chars.len() {
                    if chars[j] == ']' && j > start {
                        closed = true;
                        break;
                    }
                    if chars[j] == '\\' || chars[j] == '[' {
                        class.push('\\');
                    }
                    class.push(chars[j]);
                    j += 1;
                }
                if closed {
                    class.push(']');
                    s.push_str(&class);
                    i = j + 1;
                    continue;
                } else {
                    s.push_str("\\[");
                }
            }
            '\\' => {
                if i + 1 < chars.len() {
                    s.push_str(&regex::escape(&chars[i + 1].to_string()));
                    i += 2;
                    continue;
                }
            }
            _ => s.push_str(&regex::escape(&c.to_string())),
        }
        i += 1;
    }
    s
}

fn parse_gitignore(text: &str) -> Vec<GitPattern> {
    let mut v = vec![];
    for line in text.lines() {
        let mut l = line.trim_end_matches('\r').to_string();
        if l.is_empty() || l.starts_with('#') {
            continue;
        }
        // trim unescaped trailing spaces
        while l.ends_with(' ') && !l.ends_with("\\ ") {
            l.pop();
        }
        if l.is_empty() {
            continue;
        }
        let mut negated = false;
        if let Some(r) = l.strip_prefix('!') {
            negated = true;
            l = r.to_string();
        } else if l.starts_with("\\!") || l.starts_with("\\#") {
            l = l[1..].to_string();
        }
        let mut dir_only = false;
        if l.ends_with('/') {
            dir_only = true;
            l.pop();
        }
        if l.is_empty() {
            continue;
        }
        let anchored = l.contains('/');
        let body = l.trim_start_matches('/');
        let re = if anchored {
            format!("^{}$", glob_part_to_regex(body, false))
        } else {
            format!("^(?:.*/)?{}$", glob_part_to_regex(body, false))
        };
        if let Ok(regex) = Regex::new(&re) {
            v.push(GitPattern { regex, negated, dir_only });
        }
    }
    v
}

pub struct GitIgnore {
    repo_root: PathBuf,
    cache: HashMap<PathBuf, Vec<GitPattern>>,
    exclude: Vec<GitPattern>,
}

fn is_git_dir(p: &Path) -> bool {
    if p.is_dir() {
        return p.join("HEAD").is_file() && p.join("objects").is_dir() && p.join("refs").is_dir();
    }
    if p.is_file() {
        if let Ok(t) = fs::read_to_string(p) {
            return t.starts_with("gitdir:");
        }
    }
    false
}

impl GitIgnore {
    pub fn discover(start: &Path) -> Option<GitIgnore> {
        let mut cur = Some(start.to_path_buf());
        while let Some(dir) = cur {
            let g = dir.join(".git");
            if is_git_dir(&g) {
                let mut exclude = vec![];
                if g.is_dir() {
                    if let Ok(t) = fs::read_to_string(g.join("info").join("exclude")) {
                        exclude = parse_gitignore(&t);
                    }
                }
                return Some(GitIgnore { repo_root: dir, cache: HashMap::new(), exclude });
            }
            cur = dir.parent().map(|p| p.to_path_buf());
        }
        None
    }

    fn patterns_for(&mut self, dir: &Path) -> Vec<GitPattern> {
        if let Some(p) = self.cache.get(dir) {
            return p.clone();
        }
        let p = match fs::read_to_string(dir.join(".gitignore")) {
            Ok(t) => parse_gitignore(&t),
            Err(_) => vec![],
        };
        self.cache.insert(dir.to_path_buf(), p.clone());
        p
    }

    /// `path` must be absolute (canonical parent).
    pub fn is_ignored(&mut self, path: &Path, is_dir: bool) -> bool {
        if path.file_name().map(|n| n == ".git").unwrap_or(false) {
            return true;
        }
        let rel = match path.strip_prefix(&self.repo_root) {
            Ok(r) => r.to_path_buf(),
            Err(_) => return false,
        };
        let mut result = None;
        let rel_str = rel.to_string_lossy().to_string();
        for p in &self.exclude {
            if (!p.dir_only || is_dir) && p.regex.is_match(&rel_str) {
                result = Some(!p.negated);
            }
        }
        // walk directories from repo root to the entry's parent
        let mut dirs = vec![self.repo_root.clone()];
        let comps: Vec<_> = rel.components().collect();
        let mut acc = self.repo_root.clone();
        for c in comps.iter().take(comps.len().saturating_sub(1)) {
            acc = acc.join(c);
            dirs.push(acc.clone());
        }
        for d in dirs {
            let pats = self.patterns_for(&d);
            if pats.is_empty() {
                continue;
            }
            let sub = match path.strip_prefix(&d) {
                Ok(r) => r.to_string_lossy().to_string(),
                Err(_) => continue,
            };
            for p in &pats {
                if (!p.dir_only || is_dir) && p.regex.is_match(&sub) {
                    result = Some(!p.negated);
                }
            }
        }
        result.unwrap_or(false)
    }
}

pub struct HgIgnore {
