    patterns: Vec<Regex>,
}

impl HgIgnore {
    pub fn discover(start: &Path) -> Option<HgIgnore> {
        let mut cur = Some(start.to_path_buf());
        while let Some(dir) = cur {
            if dir.join(".hg").is_dir() {
