                            continue;
                        }
                        if let Some(s) = l.strip_prefix("syntax:") {
                            syntax_glob = s.trim() == "glob";
                            continue;
                        }
                        let (glob, pat) = if let Some(p) = l.strip_prefix("glob:") {
                            (true, p.to_string())
                        } else if let Some(p) = l.strip_prefix("re:") {
                            (false, p.to_string())
                        } else if let Some(p) = l.strip_prefix("regexp:") {
                            (false, p.to_string())
                        } else {
                            (syntax_glob, l.to_string())
                        };
                        let re = if glob {
                            format!("(?:^|/){}(?:/|$)", glob_part_to_regex(&pat, false))
                        } else {
                            pat
                        };
                        if let Ok(r) = Regex::new(&re) {
                            patterns.push(r);
                        }
                    }
                }
                return Some(HgIgnore { root: dir, patterns });
            }
            cur = dir.parent().map(|p| p.to_path_buf());
        }
        None
    }

    pub fn is_ignored(&self, path: &Path) -> bool {
        if path.file_name().map(|n| n == ".hg").unwrap_or(false) {
            return false;
        }
        let rel = match path.strip_prefix(&self.root) {
            Ok(r) => r.to_string_lossy().to_string(),
            Err(_) => return false,
        };
        self.patterns.iter().any(|r| r.is_match(&rel))
    }
}

pub struct DockerIgnore {
    root: PathBuf,
    patterns: Vec<(Regex, bool)>,
}

impl DockerIgnore {
    pub fn discover(start: &Path) -> Option<DockerIgnore> {
        let t = fs::read_to_string(start.join(".dockerignore")).ok()?;
        let mut patterns = vec![];
        for line in t.lines() {
            let l = line.trim();
            if l.is_empty() || l.starts_with('#') {
                continue;
            }
            let (neg, p) = match l.strip_prefix('!') {
                Some(p) => (true, p.trim()),
                None => (false, l),
            };
            let p = p.trim_start_matches('/').trim_end_matches('/');
            let re = format!("^(?:.*/)?{}(?:/.*)?$", glob_part_to_regex(p, true));
            if let Ok(r) = Regex::new(&re) {
                patterns.push((r, neg));
            }
        }
        Some(DockerIgnore { root: start.to_path_buf(), patterns })
    }

    pub fn is_ignored(&self, path: &Path) -> bool {
        let rel = match path.strip_prefix(&self.root) {
            Ok(r) => r.to_string_lossy().to_string(),
            Err(_) => return false,
        };
        let mut ignored = false;
        for (r, neg) in &self.patterns {
            if r.is_match(&rel) {
                ignored = !neg;
            }
        }
        ignored
    }
}
