//! Thin libc FFI wrappers.

use std::collections::HashMap;
use std::cell::RefCell;
use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int, c_void};
use std::os::unix::ffi::OsStrExt;
use std::path::Path;

#[repr(C)]
struct Passwd {
    pw_name: *mut c_char,
    pw_passwd: *mut c_char,
    pw_uid: u32,
    pw_gid: u32,
    pw_gecos: *mut c_char,
    pw_dir: *mut c_char,
    pw_shell: *mut c_char,
}

#[repr(C)]
struct Group {
    gr_name: *mut c_char,
    gr_passwd: *mut c_char,
    gr_gid: u32,
    gr_mem: *mut *mut c_char,
}

extern "C" {
    fn getpwuid(uid: u32) -> *mut Passwd;
    fn getgrgid(gid: u32) -> *mut Group;
    fn getuid() -> u32;
    fn getgid() -> u32;
    fn listxattr(path: *const c_char, list: *mut c_char, size: usize) -> isize;
    fn getxattr(path: *const c_char, name: *const c_char, value: *mut c_void, size: usize) -> isize;
    fn open(path: *const c_char, flags: c_int, ...) -> c_int;
    fn close(fd: c_int) -> c_int;
    fn ioctl(fd: c_int, req: u64, ...) -> c_int;
}

thread_local! {
    static USERS: RefCell<HashMap<u32, Option<String>>> = RefCell::new(HashMap::new());
    static GROUPS: RefCell<HashMap<u32, Option<String>>> = RefCell::new(HashMap::new());
}

pub fn user_name(uid: u32) -> Option<String> {
    USERS.with(|m| {
        let mut m = m.borrow_mut();
        if let Some(v) = m.get(&uid) {
            return v.clone();
        }
        let v = unsafe {
            let p = getpwuid(uid);
            if p.is_null() || (*p).pw_name.is_null() {
                None
            } else {
                Some(CStr::from_ptr((*p).pw_name).to_string_lossy().to_string())
            }
        };
        m.insert(uid, v.clone());
        v
    })
}

pub fn group_name(gid: u32) -> Option<String> {
    GROUPS.with(|m| {
        let mut m = m.borrow_mut();
        if let Some(v) = m.get(&gid) {
            return v.clone();
        }
        let v = unsafe {
            let p = getgrgid(gid);
            if p.is_null() || (*p).gr_name.is_null() {
                None
            } else {
                Some(CStr::from_ptr((*p).gr_name).to_string_lossy().to_string())
            }
        };
        m.insert(gid, v.clone());
        v
    })
}

pub fn current_uid() -> u32 {
    unsafe { getuid() }
}

pub fn current_gid() -> u32 {
    unsafe { getgid() }
}

fn cpath(p: &Path) -> Option<CString> {
    CString::new(p.as_os_str().as_bytes()).ok()
}

pub fn list_xattrs(p: &Path) -> Option<Vec<String>> {
    let c = cpath(p)?;
    unsafe {
        let n = listxattr(c.as_ptr(), std::ptr::null_mut(), 0);
        if n < 0 {
            return None;
        }
        if n == 0 {
            return Some(vec![]);
        }
        let mut buf = vec![0u8; n as usize];
        let n = listxattr(c.as_ptr(), buf.as_mut_ptr() as *mut c_char, buf.len());
        if n < 0 {
            return None;
        }
        buf.truncate(n as usize);
        Some(
            buf.split(|&b| b == 0)
                .filter(|s| !s.is_empty())
                .map(|s| String::from_utf8_lossy(s).to_string())
                .collect(),
        )
    }
}

pub fn get_xattr(p: &Path, name: &str) -> Option<Vec<u8>> {
    let c = cpath(p)?;
    let n = CString::new(name).ok()?;
    unsafe {
        let len = getxattr(c.as_ptr(), n.as_ptr(), std::ptr::null_mut(), 0);
        if len < 0 {
            return None;
        }
        let mut buf = vec![0u8; len as usize];
        if len == 0 {
            return Some(buf);
        }
        let len = getxattr(c.as_ptr(), n.as_ptr(), buf.as_mut_ptr() as *mut c_void, buf.len());
        if len < 0 {
            return None;
        }
        buf.truncate(len as usize);
        Some(buf)
    }
}

pub fn get_flags(p: &Path) -> Option<u32> {
    let c = cpath(p)?;
