use crate::config::Config;
use crate::field::Field;
use crate::sys;
use crate::util;
use crate::util::datetime;
use crate::util::media;
use crate::util::mime;
use crate::util::zip::ZipEntry;
use crate::value::Value;
use std::cell::RefCell;
use std::fs::{self, Metadata};
use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::time::UNIX_EPOCH;

pub struct ArchiveInfo {
    pub archive_path: String,
    pub entry: ZipEntry,
}

#[derive(Default)]
struct Cache {
    contents: Option<Option<Vec<u8>>>,
    mime: Option<Option<String>>,
    dims: Option<Option<(u64, u64)>>,
    mp3: Option<Option<media::Mp3Info>>,
    xattrs: Option<Option<Vec<String>>>,
}

pub struct FileInfo {
    pub path: PathBuf,
    pub rel: String,
    pub lmeta: Option<Metadata>,
    pub meta: Option<Metadata>,
    pub archive: Option<ArchiveInfo>,
    cache: RefCell<Cache>,
}

fn system_time_secs(t: std::io::Result<std::time::SystemTime>) -> Option<i64> {
    let t = t.ok()?;
    match t.duration_since(UNIX_EPOCH) {
        Ok(d) => Some(d.as_secs() as i64),
        Err(e) => {
            let d = e.duration();
            let s = d.as_secs() as i64;
            if d.subsec_nanos() > 0 {
                Some(-s - 1)
            } else {
                Some(-s)
            }
        }
    }
}

impl FileInfo {
    pub fn new(path: PathBuf, rel: String, follow: bool) -> FileInfo {
        let lmeta = fs::symlink_metadata(&path).ok();
        let meta = if follow { fs::metadata(&path).ok().or_else(|| lmeta.clone()) } else { lmeta.clone() };
        FileInfo { path, rel, lmeta, meta, archive: None, cache: RefCell::new(Cache::default()) }
    }

    pub fn new_archive(archive_path: String, entry: ZipEntry) -> FileInfo {
        FileInfo {
            path: PathBuf::from(&entry.name),
            rel: entry.name.trim_end_matches('/').to_string(),
            lmeta: None,
            meta: None,
            archive: Some(ArchiveInfo { archive_path, entry }),
            cache: RefCell::new(Cache::default()),
        }
    }

    pub fn is_dir(&self) -> bool {
        if let Some(a) = &self.archive {
            return a.entry.is_dir;
        }
        self.meta.as_ref().map(|m| m.is_dir()).unwrap_or(false)
    }

    pub fn is_regular_file(&self) -> bool {
        self.meta.as_ref().map(|m| m.file_type().is_file()).unwrap_or(false)
    }

    pub fn name(&self) -> String {
        let p = Path::new(&self.rel);
        match p.file_name() {
            Some(n) => n.to_string_lossy().to_string(),
            None => self.path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default(),
        }
    }

    pub fn contents(&self) -> Option<Vec<u8>> {
        if self.archive.is_some() {
            return None;
        }
        let mut c = self.cache.borrow_mut();
        if let Some(ref v) = c.contents {
            return v.clone();
        }
        let v = if self.is_dir() {
            None
        } else {
            let ft = self.meta.as_ref().map(|m| m.file_type());
            match ft {
                Some(ft) if ft.is_fifo() || ft.is_socket() || ft.is_char_device() || ft.is_block_device() => None,
                _ => fs::read(&self.path).ok(),
            }
        };
        c.contents = Some(v.clone());
        v
    }

    fn head(&self, n: usize) -> Option<Vec<u8>> {
        // read entire contents for simplicity
        self.contents().map(|c| c[..c.len().min(n)].to_vec())
    }

    pub fn mime(&self) -> Option<String> {
        {
            let c = self.cache.borrow();
            if let Some(ref m) = c.mime {
                return m.clone();
            }
        }
        let m = if self.archive.is_some() {
            None
        } else if self.is_dir() {
            Some("inode/directory".to_string())
        } else {
            self.contents().map(|d| mime::detect(&d))
        };
        self.cache.borrow_mut().mime = Some(m.clone());
        m
    }

    fn dims(&self, config: &Config) -> Option<(u64, u64)> {
        {
            let c = self.cache.borrow();
            if let Some(d) = c.dims {
                return d;
            }
        }
        let name = self.name().to_lowercase();
        let d = if self.archive.is_some() || self.is_dir() {
            None
        } else if name.ends_with(".svg") {
            self.contents().and_then(|d| media::svg_dims(&d))
        } else if util::has_extension(&name, &config.is_image) {
            self.contents().and_then(|d| media::image_dims(&d))
        } else if name.ends_with(".mp4") || name.ends_with(".m4v") || name.ends_with(".mov") {
            self.contents().and_then(|d| media::mp4_dims(&d))
        } else {
            None
        };
        self.cache.borrow_mut().dims = Some(d);
        d
    }

    fn mp3(&self) -> Option<media::Mp3Info> {
        {
            let c = self.cache.borrow();
            if let Some(ref d) = c.mp3 {
                return d.clone();
            }
        }
        let name = self.name().to_lowercase();
        let d = if self.archive.is_none() && !self.is_dir() && name.ends_with(".mp3") {
            self.contents().and_then(|d| media::mp3_info(&d))
        } else {
            None
        };
        self.cache.borrow_mut().mp3 = Some(d.clone());
        d
    }

    pub fn xattrs(&self) -> Option<Vec<String>> {
        {
            let c = self.cache.borrow();
            if let Some(ref d) = c.xattrs {
                return d.clone();
            }
        }
        let d = if self.archive.is_some() { None } else { sys::list_xattrs(&self.path) };
        self.cache.borrow_mut().xattrs = Some(d.clone());
        d
    }

    pub fn abspath(&self) -> Option<String> {
        fs::canonicalize(&self.path).ok().map(|p| p.to_string_lossy().to_string())
    }

    fn acl(&self, default: bool) -> Option<Vec<sys::AclEntry>> {
        if self.archive.is_some() {
            return None;
        }
        let name = if default { "system.posix_acl_default" } else { "system.posix_acl_access" };
        let data = sys::get_xattr(&self.path, name)?;
        sys::parse_acl(&data)
    }

    pub fn acl_string(&self, default: bool) -> Option<String> {
        let entries = self.acl(default)?;
        Some(entries.iter().map(sys::acl_entry_string).collect::<Vec<_>>().join(","))
    }

    pub fn acl_entries(&self, default: bool) -> Option<Vec<sys::AclEntry>> {
        self.acl(default)
    }

    pub fn get_field(&self, field: Field, config: &Config) -> Value {
        if let Some(a) = &self.archive {
            return self.get_archive_field(field, a, config);
        }
        let meta = match &self.meta {
            Some(m) => m,
            None => {
                return match field {
                    Field::Name => Value::Str(self.name()),
                    Field::Path => Value::Str(self.rel.clone()),
                    _ => Value::Empty,
                }
            }
        };
        let mode = meta.permissions().mode();
        match field {
            Field::Name => Value::Str(self.name()),
            Field::Filename => {
                let p = Path::new(&self.rel);
                Value::Str(p.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default())
            }
            Field::Extension => {
                let p = Path::new(&self.rel);
                Value::Str(p.extension().map(|s| s.to_string_lossy().to_string()).unwrap_or_default())
            }
            Field::Path => Value::Str(self.rel.clone()),
            Field::AbsPath => match self.abspath() {
                Some(s) => Value::Str(s),
                None => Value::Empty,
            },
            Field::Directory => {
                let p = Path::new(&self.rel);
                Value::Str(p.parent().map(|s| s.to_string_lossy().to_string()).unwrap_or_default())
            }
            Field::AbsDir => {
                let parent = self.path.parent().map(|p| if p.as_os_str().is_empty() { Path::new(".") } else { p });
                match parent.and_then(|p| fs::canonicalize(p).ok()) {
                    Some(p) => Value::Str(p.to_string_lossy().to_string()),
                    None => Value::Empty,
                }
            }
            Field::Size => Value::Int(meta.len() as i64),
            Field::FormattedSize => {
                Value::Str(util::format_size(meta.len(), &config.default_file_size_format).unwrap_or_default())
            }
            Field::Uid => Value::Int(meta.uid() as i64),
            Field::Gid => Value::Int(meta.gid() as i64),
            Field::User => match sys::user_name(meta.uid()) {
                Some(s) => Value::Str(s),
                None => Value::Empty,
            },
            Field::Group => match sys::group_name(meta.gid()) {
                Some(s) => Value::Str(s),
                None => Value::Empty,
            },
            Field::Created => match system_time_secs(meta.created()) {
                Some(t) => Value::DateTime(t),
                None => Value::Empty,
            },
            Field::Accessed => Value::DateTime(meta.atime()),
            Field::Modified => Value::DateTime(meta.mtime()),
            Field::IsDir => Value::Bool(meta.is_dir()),
            Field::IsFile => Value::Bool(meta.file_type().is_file()),
            Field::IsSymlink => Value::Bool(self.lmeta.as_ref().map(|m| m.file_type().is_symlink()).unwrap_or(false)),
            Field::IsPipe => Value::Bool(meta.file_type().is_fifo()),
            Field::IsCharacterDevice => Value::Bool(meta.file_type().is_char_device()),
            Field::IsBlockDevice => Value::Bool(meta.file_type().is_block_device()),
            Field::IsSocket => Value::Bool(meta.file_type().is_socket()),
            Field::Device => Value::Int(meta.dev() as i64),
            Field::Rdev => Value::Int(meta.rdev() as i64),
            Field::Inode => Value::Int(meta.ino() as i64),
            Field::Blocks => Value::Int(meta.blocks() as i64),
            Field::Hardlinks => Value::Int(meta.nlink() as i64),
            Field::Atime => Value::Int(meta.atime()),
            Field::Mtime => Value::Int(meta.mtime()),
            Field::Ctime => Value::Int(meta.ctime()),
            Field::Mode => Value::Str(util::mode_string(meta)),
            Field::UserRead => Value::Bool(mode & 0o400 != 0),
            Field::UserWrite => Value::Bool(mode & 0o200 != 0),
            Field::UserExec => Value::Bool(mode & 0o100 != 0),
            Field::UserAll => Value::Bool(mode & 0o700 == 0o700),
            Field::GroupRead => Value::Bool(mode & 0o040 != 0),
            Field::GroupWrite => Value::Bool(mode & 0o020 != 0),
            Field::GroupExec => Value::Bool(mode & 0o010 != 0),
            Field::GroupAll => Value::Bool(mode & 0o070 == 0o070),
            Field::OtherRead => Value::Bool(mode & 0o004 != 0),
            Field::OtherWrite => Value::Bool(mode & 0o002 != 0),
            Field::OtherExec => Value::Bool(mode & 0o001 != 0),
            Field::OtherAll => Value::Bool(mode & 0o007 == 0o007),
            Field::Suid => Value::Bool(mode & 0o4000 != 0),
            Field::Sgid => Value::Bool(mode & 0o2000 != 0),
            Field::IsSticky => Value::Bool(mode & 0o1000 != 0),
            Field::IsHidden => Value::Bool(self.name().starts_with('.')),
            Field::HasXattrs => match self.xattrs() {
                Some(v) => Value::Bool(!v.is_empty()),
                None => Value::Bool(false),
            },
            Field::XattrCount => match self.xattrs() {
                Some(v) => Value::Int(v.len() as i64),
                None => Value::Int(0),
            },
            Field::Extattrs => match sys::get_flags(&self.path) {
                Some(f) => Value::Str(sys::flags_string(f)),
                None => Value::Empty,
            },
            Field::HasExtattrs => match sys::get_flags(&self.path) {
                Some(f) => Value::Bool(!sys::flags_string(f).is_empty()),
                None => Value::Bool(false),
            },
            Field::Acl => match self.acl_string(false) {
                Some(s) => Value::Str(s),
                None => Value::Empty,
            },
            Field::HasAcl => match self.acl(false) {
                Some(e) => Value::Bool(e.iter().any(|x| matches!(x.tag, 2 | 8 | 0x10))),
                None => Value::Empty,
            },
            Field::DefaultAcl => match self.acl_string(true) {
                Some(s) => Value::Str(s),
                None => Value::Empty,
            },
            Field::HasDefaultAcl => match self.acl(true) {
                Some(e) => Value::Bool(!e.is_empty()),
                None => Value::Empty,
            },
            Field::HasCapabilities => {
                Value::Bool(sys::get_xattr(&self.path, "security.capability").is_some())
            }
            Field::Capabilities => match sys::get_xattr(&self.path, "security.capability").and_then(|d| sys::parse_caps(&d)) {
                Some((caps, eff)) => {
                    if caps.is_empty() {
                        Value::Empty
                    } else {
                        Value::Str(format!("{}{}", caps.join(","), if eff { "=ep" } else { "=p" }))
                    }
                }
                None => Value::Empty,
            },
            Field::IsShebang => Value::Bool(self.head(2).map(|h| h.starts_with(b"#!")).unwrap_or(false)),
            Field::IsEmpty => {
                if meta.is_dir() {
                    Value::Bool(fs::read_dir(&self.path).map(|mut r| r.next().is_none()).unwrap_or(false))
                } else {
                    Value::Bool(meta.len() == 0)
                }
            }
            Field::Width => match self.dims(config) {
                Some((w, _)) => Value::Int(w as i64),
                None => Value::Empty,
            },
            Field::Height => match self.dims(config) {
                Some((_, h)) => Value::Int(h as i64),
                None => Value::Empty,
            },
            Field::Duration => opt_int(self.mp3().and_then(|m| m.duration)),
            Field::Bitrate => opt_int(self.mp3().and_then(|m| m.bitrate)),
            Field::Freq => opt_int(self.mp3().and_then(|m| m.freq)),
            Field::Title => opt_str(self.mp3().and_then(|m| m.title)),
            Field::Artist => opt_str(self.mp3().and_then(|m| m.artist)),
            Field::Album => opt_str(self.mp3().and_then(|m| m.album)),
            Field::Year => opt_int(self.mp3().and_then(|m| m.year)),
            Field::Genre => opt_str(self.mp3().and_then(|m| m.genre)),
            Field::Mime => opt_str(self.mime()),
            Field::LineCount => {
                if meta.is_dir() {
                    Value::Empty
                } else {
                    match self.contents() {
                        Some(c) => Value::Int(c.iter().filter(|&&b| b == b'\n').count() as i64),
                        None => Value::Empty,
                    }
                }
            }
            Field::IsBinary => {
                if meta.is_dir() {
                    Value::Bool(false)
                } else {
                    Value::Bool(self.mime().map(|m| !mime::is_text_mime(&m)).unwrap_or(false))
                }
            }
            Field::IsText => {
                if meta.is_dir() {
                    Value::Bool(false)
                } else {
                    Value::Bool(self.mime().map(|m| mime::is_text_mime(&m)).unwrap_or(false))
                }
            }
            Field::IsArchive => Value::Bool(util::has_extension(&self.name(), &config.is_archive)),
            Field::IsAudio => Value::Bool(util::has_extension(&self.name(), &config.is_audio)),
            Field::IsBook => Value::Bool(util::has_extension(&self.name(), &config.is_book)),
            Field::IsDoc => Value::Bool(util::has_extension(&self.name(), &config.is_doc)),
            Field::IsFont => Value::Bool(util::has_extension(&self.name(), &config.is_font)),
            Field::IsImage => Value::Bool(util::has_extension(&self.name(), &config.is_image)),
            Field::IsSource => Value::Bool(util::has_extension(&self.name(), &config.is_source)),
            Field::IsVideo => Value::Bool(util::has_extension(&self.name(), &config.is_video)),
            Field::Sha1 => self.hash(util::hash::sha1_hex),
            Field::Sha256 => self.hash(util::hash::sha256_hex),
            Field::Sha512 => self.hash(util::hash::sha512_hex),
            Field::Sha3 => self.hash(util::hash::sha3_512_hex),
            _ => Value::Empty, // EXIF fields
        }
    }

    fn hash(&self, f: fn(&[u8]) -> String) -> Value {
        if self.is_dir() {
            return Value::Empty;
        }
        match self.contents() {
            Some(c) => Value::Str(f(&c)),
            None => Value::Empty,
        }
    }

    fn get_archive_field(&self, field: Field, a: &ArchiveInfo, config: &Config) -> Value {
        let e = &a.entry;
        let p = Path::new(&self.rel);
        let mode = e.mode.unwrap_or(if e.is_dir { 0o40755 } else { 0o100644 });
        match field {
            Field::Name => Value::Str(self.name()),
            Field::Filename => Value::Str(p.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default()),
            Field::Extension => Value::Str(p.extension().map(|s| s.to_string_lossy().to_string()).unwrap_or_default()),
            Field::Path | Field::AbsPath => Value::Str(self.rel.clone()),
            Field::Directory => Value::Str(p.parent().map(|s| s.to_string_lossy().to_string()).unwrap_or_default()),
            Field::Size => Value::Int(e.size as i64),
            Field::FormattedSize => Value::Str(util::format_size(e.size, &config.default_file_size_format).unwrap_or_default()),
            Field::Modified => {
                let (y, mo, d, h, mi, s) = e.datetime();
                match datetime::from_local(y, mo, d, h, mi, s) {
                    Some(t) => Value::DateTime(t),
                    None => Value::Empty,
                }
            }
            Field::IsDir => Value::Bool(e.is_dir),
            Field::IsFile => Value::Bool(!e.is_dir),
            Field::IsSymlink | Field::IsPipe | Field::IsCharacterDevice | Field::IsBlockDevice | Field::IsSocket => {
                Value::Bool(false)
            }
            Field::Mode => Value::Str(util::mode_string_from(mode, if e.is_dir { 'd' } else { '-' })),
            Field::UserRead => Value::Bool(mode & 0o400 != 0),
            Field::UserWrite => Value::Bool(mode & 0o200 != 0),
            Field::UserExec => Value::Bool(mode & 0o100 != 0),
            Field::UserAll => Value::Bool(mode & 0o700 == 0o700),
            Field::GroupRead => Value::Bool(mode & 0o040 != 0),
            Field::GroupWrite => Value::Bool(mode & 0o020 != 0),
            Field::GroupExec => Value::Bool(mode & 0o010 != 0),
            Field::GroupAll => Value::Bool(mode & 0o070 == 0o070),
            Field::OtherRead => Value::Bool(mode & 0o004 != 0),
            Field::OtherWrite => Value::Bool(mode & 0o002 != 0),
            Field::OtherExec => Value::Bool(mode & 0o001 != 0),
            Field::OtherAll => Value::Bool(mode & 0o007 == 0o007),
            Field::Suid => Value::Bool(mode & 0o4000 != 0),
            Field::Sgid => Value::Bool(mode & 0o2000 != 0),
            Field::IsSticky => Value::Bool(mode & 0o1000 != 0),
            Field::IsHidden => Value::Bool(self.name().starts_with('.')),
            Field::IsArchive => Value::Bool(util::has_extension(&self.name(), &config.is_archive)),
            Field::IsAudio => Value::Bool(util::has_extension(&self.name(), &config.is_audio)),
            Field::IsBook => Value::Bool(util::has_extension(&self.name(), &config.is_book)),
            Field::IsDoc => Value::Bool(util::has_extension(&self.name(), &config.is_doc)),
            Field::IsFont => Value::Bool(util::has_extension(&self.name(), &config.is_font)),
            Field::IsImage => Value::Bool(util::has_extension(&self.name(), &config.is_image)),
            Field::IsSource => Value::Bool(util::has_extension(&self.name(), &config.is_source)),
            Field::IsVideo => Value::Bool(util::has_extension(&self.name(), &config.is_video)),
            Field::IsEmpty => Value::Bool(e.size == 0),
            Field::HasXattrs | Field::HasExtattrs | Field::IsShebang | Field::IsBinary | Field::IsText
            | Field::HasCapabilities => Value::Bool(false),
            Field::XattrCount => Value::Int(0),
            _ => Value::Empty,
        }
    }
}

fn opt_int(v: Option<i64>) -> Value {
    match v {
        Some(i) => Value::Int(i),
        None => Value::Empty,
    }
}

fn opt_str(v: Option<String>) -> Value {
    match v {
        Some(s) => Value::Str(s),
        None => Value::Empty,
    }
}
