use crate::config::Config;
use crate::field::Field;
use crate::sys;
use crate::util;
use crate::util::datetime;
use crate::util::media;
use crate::util::mime;
use crate::util::zip::ZipEntry;
use crate::value::Value;
use std::cell::RefCell;
use std::fs::{self, Metadata};
use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::time::UNIX_EPOCH;

pub struct ArchiveInfo {
    pub archive_path: String,
    pub entry: ZipEntry,
}

#[derive(Default)]
struct Cache {
    contents: Option<Option<Vec<u8>>>,
    mime: Option<Option<String>>,
    dims: Option<Option<(u64, u64)>>,
    mp3: Option<Option<media::Mp3Info>>,
    xattrs: Option<Option<Vec<String>>>,
}

pub struct FileInfo {
    pub path: PathBuf,
    pub rel: String,
    pub lmeta: Option<Metadata>,
    pub meta: Option<Metadata>,
    pub archive: Option<ArchiveInfo>,
    cache: RefCell<Cache>,
}

fn system_time_secs(t: std::io::Result<std::time::SystemTime>) -> Option<i64> {
    let t = t.ok()?;
    match t.duration_since(UNIX_EPOCH) {
        Ok(d) => Some(d.as_secs() as i64),
        Err(e) => {
            let d = e.duration();
            let s = d.as_secs() as i64;
            if d.subsec_nanos() > 0 {
                Some(-s - 1)
            } else {
                Some(-s)
            }
        }
    }
}

impl FileInfo {
    pub fn new(path: PathBuf, rel: String, follow: bool) -> FileInfo {
        let lmeta = fs::symlink_metadata(&path).ok();
        let meta = if follow { fs::metadata(&path).ok().or_else(|| lmeta.clone()) } else { lmeta.clone() };
        FileInfo { path, rel, lmeta, meta, archive: None, cache: RefCell::new(Cache::default()) }
    }

    pub fn new_archive(archive_path: String, entry: ZipEntry) -> FileInfo {
        FileInfo {
            path: PathBuf::from(&entry.name),
            rel: entry.name.trim_end_matches('/').to_string(),
            lmeta: None,
            meta: None,
            archive: Some(ArchiveInfo { archive_path, entry }),
            cache: RefCell::new(Cache::default()),
        }
    }

    pub fn is_dir(&self) -> bool {
        if let Some(a) = &self.archive {
            return a.entry.is_dir;
        }
        self.meta.as_ref().map(|m| m.is_dir()).unwrap_or(false)
    }

    pub fn is_regular_file(&self) -> bool {
        self.meta.as_ref().map(|m| m.file_type().is_file()).unwrap_or(false)
    }

    pub fn name(&self) -> String {
        let p = Path::new(&self.rel);
        match p.file_name() {
            Some(n) => n.to_string_lossy().to_string(),
            None => self.path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default(),
        }
    }

    pub fn contents(&self) -> Option<Vec<u8>> {
        if self.archive.is_some() {
            return None;
        }
        let mut c = self.cache.borrow_mut();
        if let Some(ref v) = c.contents {
            return v.clone();
        }
        let v = if self.is_dir() {
            None
        } else {
            let ft = self.meta.as_ref().map(|m| m.file_type());
            match ft {
                Some(ft) if ft.is_fifo() || ft.is_socket() || ft.is_char_device() || ft.is_block_device() => None,
                _ => fs::read(&self.path).ok(),
            }
        };
        c.contents = Some(v.clone());
        v
    }

    fn head(&self, n: usize) -> Option<Vec<u8>> {
        // read entire contents for simplicity
        self.contents().map(|c| c[..c.len().min(n)].to_vec())
    }

    pub fn mime(&self) -> Option<String> {
        {
            let c = self.cache.borrow();
            if let Some(ref m) = c.mime {
                return m.clone();
            }
        }
        let m = if self.archive.is_some() {
            None
        } else if self.is_dir() {
            Some("inode/directory".to_string())
        } else {
            self.contents().map(|d| mime::detect(&d))
        };
        self.cache.borrow_mut().mime = Some(m.clone());
        m
    }

    fn dims(&self, config: &Config) -> Option<(u64, u64)> {
        {
            let c = self.cache.borrow();
            if let Some(d) = c.dims {
                return d;
            }
        }
        let name = self.name().to_lowercase();
        let d = if self.archive.is_some() || self.is_dir() {
            None
        } else if name.ends_with(".svg") {
            self.contents().and_then(|d| media::svg_dims(&d))
        } else if util::has_extension(&name, &config.is_image) {
            self.contents().and_then(|d| media::image_dims(&d))
        } else if name.ends_with(".mp4") || name.ends_with(".m4v") || name.ends_with(".mov") {
            self.contents().and_then(|d| media::mp4_dims(&d))
        } else {
            None
        };
        self.cache.borrow_mut().dims = Some(d);
        d
    }

    fn mp3(&self) -> Option<media::Mp3Info> {
        {
            let c = self.cache.borrow();
            if let Some(ref d) = c.mp3 {
                return d.clone();
            }
        }
        let name = self.name().to_lowercase();
        let d = if self.archive.is_none() && !self.is_dir() && name.ends_with(".mp3") {
            self.contents().and_then(|d| media::mp3_info(&d))
        } else {
            None
        };
        self.cache.borrow_mut().mp3 = Some(d.clone());
        d
    }

    pub fn xattrs(&self) -> Option<Vec<String>> {
        {
            let c = self.cache.borrow();
            if let Some(ref d) = c.xattrs {
                return d.clone();
            }
        }
        let d = if self.archive.is_some() { None } else { sys::list_xattrs(&self.path) };
        self.cache.borrow_mut().xattrs = Some(d.clone());
        d
    }

    pub fn abspath(&self) -> Option<String> {
        fs::canonicalize(&self.path).ok().map(|p| p.to_string_lossy().to_string())
    }

    fn acl(&self, default: bool) -> Option<Vec<sys::AclEntry>> {
        if self.archive.is_some() {
            return None;
        }
        let name = if default { "system.posix_acl_default" } else { "system.posix_acl_access" };
        let data = sys::get_xattr(&self.path, name)?;
        sys::parse_acl(&data)
    }

    pub fn acl_string(&self, default: bool) -> Option<String> {
        let entries = self.acl(default)?;
        Some(entries.iter().map(sys::acl_entry_string).collect::<Vec<_>>().join(","))
