use crate::query::OutputFormat;
use std::collections::BTreeMap;
use std::io::Write;

pub struct Output {
    format: OutputFormat,
    raw: String,
    columns: usize,
    json_items: Vec<String>,
    html_rows: Vec<String>,
    pub broken: bool,
}

pub fn json_escape(s: &str) -> String {
    let mut o = String::with_capacity(s.len() + 2);
    o.push('"');
    for c in s.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\n' => o.push_str("\\n"),
            '\r' => o.push_str("\\r"),
            '\t' => o.push_str("\\t"),
            '\u{8}' => o.push_str("\\b"),
            '\u{c}' => o.push_str("\\f"),
            c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)),
            c => o.push(c),
        }
    }
    o.push('"');
    o
}

pub fn html_escape(s: &str) -> String {
    let mut o = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => o.push_str("&amp;"),
            '<' => o.push_str("&lt;"),
            '>' => o.push_str("&gt;"),
            '"' => o.push_str("&quot;"),
            c => o.push(c),
        }
    }
    o
}

fn csv_field(s: &str, single: bool) -> String {
    if s.is_empty() {
        return if single { "\"\"".to_string() } else { String::new() };
    }
    if s.contains(',') || s.contains('"') || s.contains('\n') || s.contains('\r') {
        format!("\"{}\"", s.replace('"', "\"\""))
    } else {
        s.to_string()
    }
}

impl Output {
    pub fn new(format: OutputFormat, raw: &str, columns: usize) -> Output {
        Output { format, raw: raw.to_string(), columns, json_items: vec![], html_rows: vec![], broken: false }
    }

    fn write(&mut self, s: &str) {
        if self.broken {
            return;
        }
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        if lock.write_all(s.as_bytes()).is_err() {
            self.broken = true;
        }
    }

    pub fn row(&mut self, keys: &[String], values: &[String], archive: Option<&str>) {
        let mut vals: Vec<&str> = vec![];
        if let Some(a) = archive {
            if self.format != OutputFormat::Json {
                vals.push(a);
            }
        }
        for v in values {
            vals.push(v);
        }
        match self.format {
            OutputFormat::Tabs => {
                let mut s = vals.join("\t");
                s.push('\n');
                self.write(&s);
            }
            OutputFormat::Lines => {
                let mut s = String::new();
                for v in &vals {
                    s.push_str(v);
                    s.push('\n');
                }
                self.write(&s);
            }
            OutputFormat::List => {
                let mut s = String::new();
                for v in &vals {
                    s.push_str(v);
                    s.push('\0');
                }
                self.write(&s);
            }
            OutputFormat::Csv => {
                let single = vals.len() == 1;
                let mut s = vals.iter().map(|v| csv_field(v, single)).collect::<Vec<_>>().join(",");
                s.push('\n');
                self.write(&s);
            }
            OutputFormat::Json => {
                let mut map = BTreeMap::new();
                for (k, v) in keys.iter().zip(values.iter()) {
                    map.insert(k.clone(), v.clone());
                }
                if let Some(a) = archive {
                    map.insert("archive".to_string(), a.to_string());
                }
                let body = map.iter().map(|(k, v)| format!("{}:{}", json_escape(k), json_escape(v))).collect::<Vec<_>>().join(",");
                self.json_items.push(format!("{{{}}}", body));
            }
            OutputFormat::Html => {
                let mut s = String::from("<tr>");
                for v in &vals {
                    s.push_str("<td>");
                    s.push_str(&html_escape(v));
                    s.push_str("</td>");
                }
                s.push_str("</tr>");
                self.html_rows.push(s);
            }
        }
    }

    pub fn finish(&mut self) {
        match self.format {
            OutputFormat::Json => {
                let s = format!("[{}]", self.json_items.join(","));
                self.write(&s);
            }
            OutputFormat::Html => {
                let t = html_escape(&self.raw);
                let mut s = format!(
                    "<html><head><title>{}</title></head><body><table><tr><th colspan=\"{}\">{}</th></tr>",
                    t, self.columns, t
                );
                for r in &self.html_rows {
                    s.push_str(r);
                }
                s.push_str("</table></body></html>");
                self.write(&s);
            }
            _ => {}
        }
        let _ = std::io::stdout().flush();
    }
}
EOF
