use crate::config::Config;
use crate::expr::{ArithOp, Expr, ExprKind, Op};
use crate::field::{Field, FieldType};
use crate::fileinfo::FileInfo;
use crate::function::{Function, RetType};
use crate::output::Output;
use crate::query::{Query, Root, Traversal};
use crate::sys;
use crate::util;
use crate::util::datetime;
use crate::util::ignore::{DockerIgnore, GitIgnore, HgIgnore};
use crate::value::Value;
use regex::Regex;
use std::cell::{Cell, RefCell};
use std::collections::{HashMap, HashSet, VecDeque};
use std::fs;
use std::path::{Path, PathBuf};
use std::rc::Rc;

pub struct Env {
    pub config: Config,
    pub use_colors: bool,
    pub no_errors: Cell<bool>,
    pub us_dates: bool,
}

impl Env {
    pub fn error(&self, path: &str, msg: &str) {
        if self.no_errors.get() {
            return;
        }
        if self.use_colors {
            eprintln!("\x1b[33m{}\x1b[0m: {}", path, msg);
        } else {
            eprintln!("{}: {}", path, msg);
        }
    }
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum CmpType {
    Str,
    Int,
    Float,
    Bool,
    DateTime,
}

fn expr_type(e: &Expr) -> CmpType {
    match &e.kind {
        ExprKind::Field(f) | ExprKind::AliasField(_, f) => match f.field_type() {
            FieldType::Str => CmpType::Str,
            FieldType::Int => CmpType::Int,
            FieldType::Bool => CmpType::Bool,
            FieldType::DateTime => CmpType::DateTime,
        },
        ExprKind::Function(f, _) => match f.ret_type() {
            RetType::Str | RetType::DateTime => CmpType::Str,
            RetType::Int => CmpType::Int,
            RetType::Float => CmpType::Float,
            RetType::Bool => CmpType::Bool,
        },
        ExprKind::Arith(..) => CmpType::Float,
        ExprKind::Value(_) => CmpType::Str,
        _ => CmpType::Bool,
    }
}

struct Group {
    key_values: HashMap<String, Value>,
    rows: usize,
    agg_values: HashMap<String, Vec<String>>,
}

struct Sorted {
    keys: Vec<Value>,
    values: Vec<String>,
    archive: Option<String>,
}

pub struct Searcher<'a> {
    env: &'a Env,
    query: &'a Query,
    aggregate: bool,
    pub had_error: bool,
    regex_cache: RefCell<HashMap<String, Result<Regex, String>>>,
    bindings: Vec<(String, Rc<FileInfo>)>,
    subquery_cache: RefCell<HashMap<usize, Vec<String>>>,
    // output handling
    collect_only: bool,
    collected: Vec<Vec<String>>,
    output: Option<Output>,
    keys: Vec<String>,
    emitted: usize,
    skipped: usize,
    done: bool,
    sorted: Vec<Sorted>,
    groups: Vec<(Vec<String>, Group)>,
    group_index: HashMap<Vec<String>, usize>,
    agg_exprs: Vec<Expr>,
}

impl<'a> Searcher<'a> {
    pub fn new(env: &'a Env, query: &'a Query) -> Searcher<'a> {
        let aggregate = query.is_aggregate();
        let keys = query
            .fields
            .iter()
            .map(|f| if aggregate { f.to_string().to_lowercase() } else { f.to_string() })
            .collect();
        let mut agg_exprs: Vec<Expr> = vec![];
        {
            let mut v = vec![];
            for f in &query.fields {
                f.collect_aggregates(&mut v);
            }
            for f in &query.ordering {
                f.collect_aggregates(&mut v);
            }
            let mut seen = HashSet::new();
            for e in v {
                let k = e.to_string();
                if seen.insert(k) {
                    agg_exprs.push(e.clone());
                }
            }
        }
        Searcher {
            env,
            query,
            aggregate,
            had_error: false,
            regex_cache: RefCell::new(HashMap::new()),
            bindings: vec![],
            subquery_cache: RefCell::new(HashMap::new()),
            collect_only: false,
            collected: vec![],
            output: None,
            keys,
            emitted: 0,
            skipped: 0,
            done: false,
            sorted: vec![],
            groups: vec![],
            group_index: HashMap::new(),
            agg_exprs,
        }
    }

    fn config(&self) -> &Config {
        &self.env.config
    }

    pub fn run(&mut self) -> bool {
        self.output = Some(Output::new(self.query.output, &self.query.raw, self.query.fields.len()));
        self.search_all();
        self.finish_results();
        if let Some(o) = self.output.as_mut() {
            o.finish();
        }
        self.had_error
    }

    fn run_collect(env: &Env, query: &Query, bindings: &[(String, Rc<FileInfo>)], limit_one: bool) -> (Vec<Vec<String>>, bool) {
        let mut s = Searcher::new(env, query);
        s.collect_only = true;
        s.bindings = bindings.to_vec();
        if limit_one && !s.aggregate && s.query.ordering.is_empty() {
            s.done = false;
        }
        s.search_all_with_limit(if limit_one { Some(1) } else { None });
        s.finish_results();
        (s.collected, s.had_error)
    }

    fn search_all(&mut self) {
        self.search_all_with_limit(None);
    }

    fn search_all_with_limit(&mut self, extra_limit: Option<usize>) {
        let roots = self.query.roots.clone();
        let _ = extra_limit;
        self.extra_limit = extra_limit;
        for root in &roots {
            self.search_root(root);
        }
    }

    fn effective_limit(&self) -> usize {
        match self.extra_limit {
            Some(l) => {
                if self.query.limit == 0 {
                    l
                } else {
                    self.query.limit.min(l)
                }
            }
            None => self.query.limit,
        }
    }
}
