    }

    fn search_all(&mut self) {
        self.search_all_with_limit(None);
    }

    fn search_all_with_limit(&mut self, extra_limit: Option<usize>) {
        let roots = self.query.roots.clone();
        let _ = extra_limit;
        self.extra_limit = extra_limit;
        for root in &roots {
            self.search_root(root);
        }
    }

    fn effective_limit(&self) -> usize {
        match self.extra_limit {
            Some(l) => {
                if self.query.limit == 0 {
                    l
                } else {
                    self.query.limit.min(l)
                }
            }
            None => self.query.limit,
        }
    }
