use crate::config::Config;
use crate::expr::{ArithOp, Expr, ExprKind, Op};
use crate::field::{Field, FieldType};
use crate::fileinfo::FileInfo;
use crate::function::{Function, RetType};
use crate::output::Output;
use crate::query::{Query, Root, Traversal};
use crate::sys;
use crate::util;
use crate::util::datetime;
use crate::util::ignore::{DockerIgnore, GitIgnore, HgIgnore};
use crate::util::zip;
use crate::value::Value;
use regex::Regex;
use std::cell::{Cell, RefCell};
use std::cmp::Ordering;
use std::collections::{HashMap, HashSet, VecDeque};
use std::fs;
use std::path::{Path, PathBuf};
use std::rc::Rc;

pub struct Env {
    pub config: Config,
    pub use_colors: bool,
    pub no_errors: Cell<bool>,
    pub us_dates: bool,
}

impl Env {
    pub fn error(&self, path: &str, msg: &str) {
        if self.no_errors.get() {
            return;
        }
        if self.use_colors {
            eprintln!("\x1b[33m{}\x1b[0m: {}", path, msg);
        } else {
            eprintln!("{}: {}", path, msg);
        }
    }
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum CmpType {
    Str,
    Int,
    Float,
    Bool,
    DateTime,
}

fn expr_type(e: &Expr) -> CmpType {
    match &e.kind {
        ExprKind::Field(f) | ExprKind::AliasField(_, f) => match f.field_type() {
            FieldType::Str => CmpType::Str,
            FieldType::Int => CmpType::Int,
            FieldType::Bool => CmpType::Bool,
            FieldType::DateTime => CmpType::DateTime,
        },
        ExprKind::Function(f, _) => match f.ret_type() {
            RetType::Str | RetType::DateTime => CmpType::Str,
            RetType::Int => CmpType::Int,
            RetType::Float => CmpType::Float,
            RetType::Bool => CmpType::Bool,
        },
        ExprKind::Arith(..) => CmpType::Float,
        ExprKind::Value(_) => CmpType::Str,
        _ => CmpType::Bool,
    }
}

struct Group {
    key_values: HashMap<String, Value>,
    rows: usize,
    agg_values: HashMap<String, Vec<String>>,
}

struct SortedRow {
    keys: Vec<Value>,
    values: Vec<String>,
    archive: Option<String>,
}

struct Ignores {
    git: Option<GitIgnore>,
    hg: Option<HgIgnore>,
    docker: Option<DockerIgnore>,
}

pub struct Searcher<'a> {
    env: &'a Env,
    query: &'a Query,
    aggregate: bool,
    pub had_error: bool,
    regex_cache: RefCell<HashMap<String, Result<Regex, String>>>,
    bindings: Vec<(String, Rc<FileInfo>)>,
    subquery_cache: RefCell<HashMap<usize, (Vec<String>, CmpType)>>,
    collect_only: bool,
    collected: Vec<Vec<String>>,
    output: Option<Output>,
    keys: Vec<String>,
    emitted: usize,
    skipped: usize,
    done: bool,
    limit: usize,
    sorted: Vec<SortedRow>,
    groups: Vec<(Vec<String>, Group)>,
    group_index: HashMap<Vec<String>, usize>,
    agg_exprs: Vec<Expr>,
    cur_alias: Option<String>,
}

const AGG_ERR: &str = "";

impl<'a> Searcher<'a> {
    pub fn new(env: &'a Env, query: &'a Query) -> Searcher<'a> {
        let aggregate = query.is_aggregate();
        let keys = query
            .fields
            .iter()
            .map(|f| if aggregate { f.to_string().to_lowercase() } else { f.to_string() })
            .collect();
        let mut agg_exprs: Vec<Expr> = vec![];
        {
            let mut v = vec![];
            for f in &query.fields {
                f.collect_aggregates(&mut v);
            }
            for f in &query.ordering {
                f.collect_aggregates(&mut v);
            }
            let mut seen = HashSet::new();
            for e in v {
                let k = e.to_string();
                if seen.insert(k) {
                    agg_exprs.push(e.clone());
                }
            }
        }
        Searcher {
            env,
            query,
            aggregate,
            had_error: false,
            regex_cache: RefCell::new(HashMap::new()),
            bindings: vec![],
            subquery_cache: RefCell::new(HashMap::new()),
            collect_only: false,
            collected: vec![],
            output: None,
            keys,
            emitted: 0,
            skipped: 0,
            done: false,
            limit: query.limit,
            sorted: vec![],
            groups: vec![],
            group_index: HashMap::new(),
            agg_exprs,
            cur_alias: None,
        }
    }

    fn config(&self) -> &Config {
        &self.env.config
    }

    /// Runs the query printing results. Returns true if an error occurred.
    pub fn run(&mut self) -> bool {
        self.output = Some(Output::new(self.query.output, &self.query.raw, self.query.fields.len()));
        self.search_roots();
        self.finish_results();
        if let Some(o) = self.output.as_mut() {
            o.finish();
            if o.broken {
                self.env.error("output", "broken pipe");
            }
        }
        self.had_error
    }

    fn run_collect(&self, query: &Query, limit_one: bool) -> Vec<Vec<String>> {
        let mut s = Searcher::new(self.env, query);
        s.collect_only = true;
        s.bindings = self.bindings.clone();
        if limit_one && !s.aggregate && query.ordering.is_empty() {
            s.limit = if s.limit == 0 { 1 } else { s.limit.min(1) };
        }
        s.search_roots();
        s.finish_results();
        s.collected
    }

    fn search_roots(&mut self) {
        let roots = self.query.roots.clone();
        for root in &roots {
            self.search_root(root);
        }
    }

    // ---------------------------------------------------------------- traversal

    fn expand_root(path: &str) -> String {
        if path == "~" {
            return std::env::var("HOME").unwrap_or_else(|_| path.to_string());
        }
        if let Some(rest) = path.strip_prefix("~/") {
            if let Ok(h) = std::env::var("HOME") {
                return format!("{}/{}", h.trim_end_matches('/'), rest);
            }
        }
        path.to_string()
    }

    fn search_root(&mut self, root: &Root) {
        if root.regexp {
            self.search_regexp_root(root);
            return;
        }
        let root_str = Searcher::expand_root(&root.path);
        let root_path = PathBuf::from(&root_str);
        let canonical = match fs::canonicalize(&root_path) {
            Ok(c) => c,
            Err(e) => {
                self.env.error(&root.path, &format!("could not canonicalize path: {}", e));
                self.had_error = true;
                return;
            }
        };
        if self.done {
            return;
        }
        self.walk(root, &root_path, &canonical);
    }

    fn search_regexp_root(&mut self, root: &Root) {
        let re = match Regex::new(&format!("^(?:{})$", root.path)) {
            Ok(r) => r,
            Err(e) => {
                self.env.error(&root.path, &e.to_string());
                self.had_error = true;
                return;
            }
        };
        // find the literal directory prefix
        let mut base = String::new();
        let mut cur = String::new();
        for c in root.path.chars() {
            if "\\.+*?()|[]{}^$".contains(c) {
                break;
            }
            cur.push(c);
            if c == '/' {
                base = cur.clone();
            }
        }
        if base.is_empty() {
            base = ".".to_string();
        }
        let mut matches = vec![];
        let mut queue = VecDeque::new();
        queue.push_back(PathBuf::from(&base));
        while let Some(d) = queue.pop_front() {
            if let Ok(rd) = fs::read_dir(&d) {
                for e in rd.flatten() {
                    let p = e.path();
                    if p.is_dir() {
                        let s = p.to_string_lossy().to_string();
                        if re.is_match(&s) {
                            matches.push(s);
                        } else {
                            queue.push_back(p);
                        }
                    }
                }
            }
        }
        for m in matches {
            if self.done {
                break;
            }
            let mut r = root.clone();
            r.regexp = false;
            r.path = m;
            self.search_root(&r);
        }
    }

    fn make_ignores(&self, root: &Root, canonical: &Path) -> Ignores {
        let git = if root.gitignore.unwrap_or(self.config().gitignore) { GitIgnore::discover(canonical) } else { None };
        let hg = if root.hgignore.unwrap_or(self.config().hgignore) { HgIgnore::discover(canonical) } else { None };
        let docker =
            if root.dockerignore.unwrap_or(self.config().dockerignore) { DockerIgnore::discover(canonical) } else { None };
        Ignores { git, hg, docker }
    }

    fn is_ignored(&self, ign: &mut Ignores, path: &Path, is_dir: bool) -> bool {
        if ign.git.is_none() && ign.hg.is_none() && ign.docker.is_none() {
            return false;
        }
        let abs = match path.parent() {
            Some(p) => {
                let p = if p.as_os_str().is_empty() { Path::new(".") } else { p };
                match fs::canonicalize(p) {
                    Ok(c) => c.join(path.file_name().unwrap_or_default()),
                    Err(_) => return false,
                }
            }
            None => return false,
        };
        if let Some(g) = ign.git.as_mut() {
            if g.is_ignored(&abs, is_dir) {
                return true;
            }
        }
        if let Some(h) = ign.hg.as_ref() {
            if h.is_ignored(&abs) {
                return true;
            }
        }
        if let Some(d) = ign.docker.as_ref() {
            if d.is_ignored(&abs) {
                return true;
            }
        }
        false
    }

    fn rel_path(root_path: &Path, path: &Path) -> String {
        match path.strip_prefix(root_path) {
            Ok(r) => r.to_string_lossy().to_string(),
            Err(_) => path.to_string_lossy().to_string(),
        }
    }

    fn walk(&mut self, root: &Root, root_path: &Path, canonical: &Path) {
        let mut ign = self.make_ignores(root, canonical);
        let mut visited: HashSet<PathBuf> = HashSet::new();
        if root.symlinks {
            visited.insert(canonical.to_path_buf());
        }
        self.cur_alias = root.alias.clone();
        match root.traversal {
            Traversal::Bfs => {
                let mut queue: VecDeque<(PathBuf, u32)> = VecDeque::new();
                queue.push_back((root_path.to_path_buf(), 1));
                while let Some((dir, depth)) = queue.pop_front() {
                    if self.done {
                        break;
                    }
                    let entries = match self.read_dir(&dir) {
                        Some(e) => e,
                        None => continue,
                    };
                    for path in entries {
                        if self.done {
                            break;
                        }
                        if let Some(next) = self.visit(root, root_path, &path, depth, &mut ign, &mut visited) {
                            queue.push_back((next, depth + 1));
                        }
                    }
                }
            }
            Traversal::Dfs => {
                self.dfs(root, root_path, &root_path.to_path_buf(), 1, &mut ign, &mut visited);
            }
        }
    }

    fn dfs(&mut self, root: &Root, root_path: &Path, dir: &Path, depth: u32, ign: &mut Ignores, visited: &mut HashSet<PathBuf>) {
        let entries = match self.read_dir(dir) {
            Some(e) => e,
            None => return,
        };
        for path in entries {
            if self.done {
                return;
            }
            if let Some(next) = self.visit(root, root_path, &path, depth, ign, visited) {
                self.dfs(root, root_path, &next, depth + 1, ign, visited);
            }
        }
    }

    fn read_dir(&mut self, dir: &Path) -> Option<Vec<PathBuf>> {
        match fs::read_dir(dir) {
            Ok(rd) => {
                let mut v = vec![];
                for e in rd {
                    match e {
                        Ok(e) => v.push(e.path()),
                        Err(err) => {
                            self.env.error(&dir.to_string_lossy(), &err.to_string());
                            self.had_error = true;
                        }
                    }
                }
                Some(v)
            }
            Err(e) => {
                self.env.error(&dir.to_string_lossy(), &e.to_string());
                self.had_error = true;
                None
            }
        }
    }

    /// Processes an entry; returns a directory to descend into, if any.
    fn visit(
        &mut self,
        root: &Root,
        root_path: &Path,
        path: &Path,
        depth: u32,
        ign: &mut Ignores,
        visited: &mut HashSet<PathBuf>,
    ) -> Option<PathBuf> {
        let rel = Searcher::rel_path(root_path, path);
        let fi = Rc::new(FileInfo::new(path.to_path_buf(), rel, root.symlinks));
        let is_dir = fi.is_dir();
        if self.is_ignored(ign, path, is_dir) {
            return None;
        }
        let ok = if depth >= root.min_depth { self.process(&fi) } else { true };
        if !ok {
            return None;
        }
        if root.archives && !is_dir && util::has_extension(&fi.name(), &self.config().is_zip_archive.clone()) {
            self.process_archive(&fi);
        }
        if is_dir && (root.max_depth == 0 || depth < root.max_depth) {
            if root.symlinks {
                let canonical = match fs::canonicalize(path) {
                    Ok(c) => c,
                    Err(_) => return None,
                };
                if visited.contains(&canonical) {
                    return None;
                }
                visited.insert(canonical.clone());
                let is_link = fi.lmeta.as_ref().map(|m| m.file_type().is_symlink()).unwrap_or(false);
                if is_link {
                    return Some(canonical);
                }
            }
            return Some(path.to_path_buf());
        }
        None
    }

    fn process_archive(&mut self, fi: &Rc<FileInfo>) {
        let data = match fs::read(&fi.path) {
            Ok(d) => d,
            Err(_) => return,
        };
        let entries = match zip::list(&data) {
            Some(e) => e,
            None => return,
        };
        let archive_path = format!("[{}]", fi.path.to_string_lossy());
        for e in entries {
            if self.done {
                return;
            }
            let afi = Rc::new(FileInfo::new_archive(archive_path.clone(), e));
            self.process(&afi);
        }
    }

    /// Evaluates the query against one entry. Returns false on error.
    fn process(&mut self, fi: &Rc<FileInfo>) -> bool {
        if self.done {
            return true;
        }
        let pushed = if let Some(a) = self.cur_alias.clone() {
            self.bindings.push((a, fi.clone()));
            true
        } else {
            false
        };
        let r = self.process_inner(fi);
        if pushed {
            self.bindings.pop();
        }
        match r {
            Ok(()) => true,
            Err(msg) => {
                let p = fi.path.to_string_lossy().to_string();
                self.env.error(&p, &msg);
                self.had_error = true;
                false
            }
        }
    }

    fn process_inner(&mut self, fi: &Rc<FileInfo>) -> Result<(), String> {
        if let Some(expr) = &self.query.expr {
            if !self.eval_cond(expr, fi)? {
                return Ok(());
            }
        }
        if self.aggregate {
            return self.accumulate(fi);
        }
        let mut values = vec![];
        for f in &self.query.fields {
            values.push(self.eval(f, Some(fi))?.to_str());
        }
        let archive = fi.archive.as_ref().map(|a| a.archive_path.clone());
        if !self.query.ordering.is_empty() {
            let mut keys = vec![];
            for o in &self.query.ordering {
                keys.push(self.sort_value(o, fi)?);
            }
            self.sorted.push(SortedRow { keys, values, archive });
            return Ok(());
        }
        self.emit(values, archive);
        Ok(())
    }

    fn sort_value(&self, e: &Expr, fi: &Rc<FileInfo>) -> Result<Value, String> {
        if let ExprKind::Field(Field::FormattedSize) = e.kind {
            return self.eval(&Expr::field(Field::Size), Some(fi));
        }
        let v = self.eval(e, Some(fi))?;
        Ok(typed_sort_value(expr_type(e), v))
    }

    fn emit(&mut self, values: Vec<String>, archive: Option<String>) {
        if self.done {
            return;
        }
        if self.skipped < self.query.offset {
            self.skipped += 1;
            return;
        }
        if self.collect_only {
            self.collected.push(values);
        } else if let Some(o) = self.output.as_mut() {
            o.row(&self.keys, &values, archive.as_deref());
            if o.broken {
                self.done = true;
            }
        }
        self.emitted += 1;
        if self.limit > 0 && self.emitted >= self.limit {
            self.done = true;
        }
    }

    fn finish_results(&mut self) {
        if self.aggregate {
            self.finish_aggregate();
            return;
        }
        if !self.query.ordering.is_empty() {
            let mut rows = std::mem::take(&mut self.sorted);
            let asc = self.query.ordering_asc.clone();
            rows.sort_by(|a, b| compare_keys(&a.keys, &b.keys, &asc));
            for r in rows {
                if self.done {
                    break;
                }
                self.emit(r.values, r.archive);
            }
        }
    }

    // ---------------------------------------------------------------- aggregation

    fn accumulate(&mut self, fi: &Rc<FileInfo>) -> Result<(), String> {
        let mut key = vec![];
        let mut kv = HashMap::new();
        for g in &self.query.grouping {
            let v = self.eval(g, Some(fi))?;
            key.push(v.to_str());
            kv.insert(g.to_string().to_lowercase(), v);
        }
        let mut agg_vals: Vec<(String, Option<String>)> = vec![];
        for a in &self.agg_exprs {
            let k = a.to_string();
            if let ExprKind::Function(_, args) = &a.kind {
                match args.first() {
                    Some(arg) if arg.has_field() => {
                        let v = self.eval(arg, Some(fi))?;
                        agg_vals.push((k, Some(v.to_str())));
                    }
                    _ => agg_vals.push((k, None)),
                }
            }
        }
        let idx = match self.group_index.get(&key) {
            Some(i) => *i,
            None => {
                self.groups.push((key.clone(), Group { key_values: kv, rows: 0, agg_values: HashMap::new() }));
                self.group_index.insert(key, self.groups.len() - 1);
                self.groups.len() - 1
            }
        };
        let g = &mut self.groups[idx].1;
        g.rows += 1;
        for (k, v) in agg_vals {
            let e = g.agg_values.entry(k).or_default();
            if let Some(v) = v {
                e.push(v);
            }
        }
        Ok(())
    }

    fn finish_aggregate(&mut self) {
        if self.groups.is_empty() && self.query.grouping.is_empty() {
            self.groups.push((vec![], Group { key_values: HashMap::new(), rows: 0, agg_values: HashMap::new() }));
        }
        let groups = std::mem::take(&mut self.groups);
        let mut rows: Vec<SortedRow> = vec![];
        for (_, g) in &groups {
            let mut values = vec![];
            for f in &self.query.fields {
                values.push(self.eval_agg(f, g).to_str());
            }
            let mut keys = vec![];
            for o in &self.query.ordering {
                keys.push(typed_sort_value(expr_type(o), self.eval_agg(o, g)));
            }
            rows.push(SortedRow { keys, values, archive: None });
        }
        if !self.query.ordering.is_empty() {
            let asc = self.query.ordering_asc.clone();
            rows.sort_by(|a, b| compare_keys(&a.keys, &b.keys, &asc));
        }
        // limit in aggregate mode applies to output rows
        self.done = false;
        for r in rows {
            if self.done {
                break;
            }
            self.emit(r.values, None);
        }
    }

    fn eval_agg(&self, e: &Expr, g: &Group) -> Value {
        let disp = e.to_string().to_lowercase();
        if let Some(v) = g.key_values.get(&disp) {
            return v.clone();
        }
        match &e.kind {
            ExprKind::Field(_) | ExprKind::AliasField(..) => Value::Empty,
            ExprKind::Value(v) => Value::Str(v.clone()),
            ExprKind::Function(f, args) if f.is_aggregate() => {
                let vals = g.agg_values.get(&e.to_string()).cloned().unwrap_or_default();
                aggregate_value(*f, g.rows, &vals)
            }
            ExprKind::Function(f, args) => {
                let vals: Vec<Value> = args.iter().map(|a| self.eval_agg(a, g)).collect();
                self.apply_function(*f, &vals, None).unwrap_or(Value::Empty)
            }
            ExprKind::Arith(l, op, r) => {
                let lv = self.eval_agg(l, g);
                let rv = self.eval_agg(r, g);
                arith(&lv, *op, &rv).unwrap_or(Value::Empty)
            }
            ExprKind::Cmp(l, _, _) => self.eval_agg(l, g),
            _ => Value::Empty,
        }
    }

    // ---------------------------------------------------------------- evaluation

    fn lookup_alias(&self, alias: &str) -> Option<Rc<FileInfo>> {
        for (a, f) in self.bindings.iter().rev() {
            if a == alias {
                return Some(f.clone());
            }
        }
        None
    }

    pub fn eval(&self, e: &Expr, fi: Option<&Rc<FileInfo>>) -> Result<Value, String> {
        match &e.kind {
            ExprKind::Field(f) => match fi {
                Some(fi) => Ok(fi.get_field(*f, self.config())),
                None => Ok(Value::Empty),
            },
            ExprKind::AliasField(a, f) => match self.lookup_alias(a) {
                Some(other) => Ok(other.get_field(*f, self.config())),
                None => match fi {
                    Some(fi) => Ok(fi.get_field(*f, self.config())),
                    None => Ok(Value::Empty),
                },
            },
            ExprKind::Value(v) => Ok(Value::Str(v.clone())),
            ExprKind::Function(f, args) => {
                if f.is_aggregate() {
                    return Ok(Value::Empty);
                }
                let mut vals = vec![];
                for a in args {
                    vals.push(self.eval(a, fi)?);
                }
                self.apply_function(*f, &vals, fi.map(|x| x.as_ref()))
            }
            ExprKind::Arith(l, op, r) => {
                let lv = self.eval(l, fi)?;
                let rv = self.eval(r, fi)?;
                arith(&lv, *op, &rv)
            }
            ExprKind::Cmp(l, _, _) => self.eval(l, fi),
            _ => match fi {
                Some(fi) => Ok(Value::Bool(self.eval_cond(e, fi)?)),
                None => Ok(Value::Empty),
            },
        }
    }

    fn get_regex(&self, pattern: &str) -> Result<Regex, String> {
        let mut c = self.regex_cache.borrow_mut();
        if let Some(r) = c.get(pattern) {
            return r.clone();
        }
        let r = Regex::new(pattern).map_err(|e| e.to_string());
        c.insert(pattern.to_string(), r.clone());
        r
    }

    fn eval_cond(&self, e: &Expr, fi: &Rc<FileInfo>) -> Result<bool, String> {
        match &e.kind {
            ExprKind::And(l, r) => Ok(self.eval_cond(l, fi)? && self.eval_cond(r, fi)?),
            ExprKind::Or(l, r) => Ok(self.eval_cond(l, fi)? || self.eval_cond(r, fi)?),
            ExprKind::Not(x) => Ok(!self.eval_cond(x, fi)?),
            ExprKind::Cmp(l, op, r) => {
                let t = expr_type(l);
                let lv = self.eval(l, Some(fi))?;
                let rv = self.eval(r, Some(fi))?;
                self.compare(t, &lv, *op, &rv.to_str())
            }
            ExprKind::Between(x, lo, hi, neg) => {
                let t = expr_type(x);
                let xv = self.eval(x, Some(fi))?;
                let lov = self.eval(lo, Some(fi))?.to_str();
                let hiv = self.eval(hi, Some(fi))?.to_str();
                let r = self.compare(t, &xv, Op::Gte, &lov)? && self.compare(t, &xv, Op::Lte, &hiv)?;
                Ok(r != *neg)
            }
            ExprKind::InList(x, list, neg) => {
                let t = expr_type(x);
                let xv = self.eval(x, Some(fi))?;
                if t == CmpType::DateTime {
                    return Err("Can't parse datetime: ".to_string());
                }
                let mut found = false;
                for item in list {
                    let iv = self.eval(item, Some(fi))?.to_str();
                    if self.compare(t, &xv, Op::Eeq, &iv)? {
                        found = true;
                        break;
                    }
                }
                Ok(found != *neg)
            }
            ExprKind::InQuery(x, q, neg) => {
                let t = expr_type(x);
                let xv = self.eval(x, Some(fi))?;
                let key = Rc::as_ptr(q) as usize;
                let correlated = query_is_correlated(q);
                let values = if !correlated {
                    let cached = self.subquery_cache.borrow().get(&key).map(|v| v.0.clone());
                    match cached {
                        Some(v) => v,
                        None => {
                            let rows = self.run_collect(q, false);
                            let v: Vec<String> = rows.into_iter().filter_map(|r| r.into_iter().next()).collect();
                            self.subquery_cache.borrow_mut().insert(key, (v.clone(), t));
                            v
                        }
                    }
                } else {
                    let rows = self.run_collect(q, false);
                    rows.into_iter().filter_map(|r| r.into_iter().next()).collect()
                };
                let mut found = false;
                for v in &values {
                    if t == CmpType::DateTime {
                        if xv.to_str() == *v {
                            found = true;
                            break;
                        }
                    } else if self.compare(t, &xv, Op::Eeq, v)? {
                        found = true;
                        break;
                    }
                }
                Ok(found != *neg)
            }
            ExprKind::Exists(q, neg) => {
                let rows = self.run_collect(q, true);
                Ok(!rows.is_empty() != *neg)
            }
            ExprKind::Field(f) => {
                if f.is_boolean() {
                    Ok(fi.get_field(*f, self.config()).to_bool())
                } else {
                    Ok(false)
                }
            }
            ExprKind::AliasField(_, f) => {
                if f.is_boolean() {
                    Ok(self.eval(e, Some(fi))?.to_bool())
                } else {
                    Ok(false)
                }
            }
            ExprKind::Function(f, _) => {
                if f.ret_type() == RetType::Bool {
                    Ok(self.eval(e, Some(fi))?.to_bool())
                } else {
                    self.eval(e, Some(fi))?;
                    Ok(false)
                }
            }
            _ => {
                self.eval(e, Some(fi))?;
                Ok(false)
            }
        }
    }

    fn compare(&self, t: CmpType, lv: &Value, op: Op, r: &str) -> Result<bool, String> {
        match t {
            CmpType::Str => {
                let l = lv.to_str();
                Ok(match op {
                    Op::Eq | Op::Ne => {
                        let m = if util::is_glob(r) {
                            self.get_regex(&util::glob_to_regex(r))?.is_match(&l)
                        } else {
                            l == r
                        };
                        if op == Op::Eq {
                            m
                        } else {
                            !m
                        }
                    }
                    Op::Eeq => l == r,
                    Op::Ene => l != r,
                    Op::Gt => l.as_str() > r,
                    Op::Gte => l.as_str() >= r,
                    Op::Lt => l.as_str() < r,
                    Op::Lte => l.as_str() <= r,
                    Op::Rx => self.get_regex(r)?.is_match(&l),
                    Op::NotRx => !self.get_regex(r)?.is_match(&l),
                    Op::Like => self.get_regex(&util::like_to_regex(r))?.is_match(&l),
                    Op::NotLike => !self.get_regex(&util::like_to_regex(r))?.is_match(&l),
                })
            }
            CmpType::Int => {
                let l = lv.to_i64_opt();
                let rr = if r.is_empty() { None } else { Some(util::str_to_i64(r)) };
                Ok(match op {
                    Op::Eq | Op::Eeq => l == rr,
                    Op::Ne | Op::Ene => l != rr,
                    Op::Gt => l > rr,
                    Op::Gte => l >= rr,
                    Op::Lt => l < rr,
                    Op::Lte => l <= rr,
                    Op::Rx => self.get_regex(r)?.is_match(&lv.to_str()),
                    Op::NotRx => !self.get_regex(r)?.is_match(&lv.to_str()),
                    Op::Like => self.get_regex(&util::like_to_regex(r))?.is_match(&lv.to_str()),
                    Op::NotLike => !self.get_regex(&util::like_to_regex(r))?.is_match(&lv.to_str()),
                })
            }
            CmpType::Float => {
                let l = lv.to_f64_opt();
                let rr = if r.is_empty() { None } else { Some(util::str_to_f64(r)) };
                let ord = match (l, rr) {
                    (None, None) => Some(Ordering::Equal),
                    (None, Some(_)) => Some(Ordering::Less),
                    (Some(_), None) => Some(Ordering::Greater),
                    (Some(a), Some(b)) => a.partial_cmp(&b),
                };
                Ok(match op {
                    Op::Eq | Op::Eeq => ord == Some(Ordering::Equal),
                    Op::Ne | Op::Ene => ord != Some(Ordering::Equal),
                    Op::Gt => ord == Some(Ordering::Greater),
                    Op::Gte => matches!(ord, Some(Ordering::Greater) | Some(Ordering::Equal)),
                    Op::Lt => ord == Some(Ordering::Less),
                    Op::Lte => matches!(ord, Some(Ordering::Less) | Some(Ordering::Equal)),
                    Op::Rx => self.get_regex(r)?.is_match(&lv.to_str()),
                    Op::NotRx => !self.get_regex(r)?.is_match(&lv.to_str()),
                    Op::Like => self.get_regex(&util::like_to_regex(r))?.is_match(&lv.to_str()),
                    Op::NotLike => !self.get_regex(&util::like_to_regex(r))?.is_match(&lv.to_str()),
                })
            }
            CmpType::Bool => {
                let l = lv.to_bool();
                let rr = util::str_to_bool(r);
                Ok(match op {
                    Op::Eq | Op::Eeq => l == rr,
                    Op::Ne | Op::Ene => l != rr,
                    Op::Gt => l & !rr,
                    Op::Gte => l >= rr,
                    Op::Lt => !l & rr,
                    Op::Lte => l <= rr,
                    Op::Rx => self.get_regex(r)?.is_match(&lv.to_str()),
                    Op::NotRx => !self.get_regex(r)?.is_match(&lv.to_str()),
                    Op::Like => self.get_regex(&util::like_to_regex(r))?.is_match(&lv.to_str()),
                    Op::NotLike => !self.get_regex(&util::like_to_regex(r))?.is_match(&lv.to_str()),
                })
            }
            CmpType::DateTime => {
                let (start, end) = datetime::parse_datetime(r, self.env.us_dates)?;
                let l = match lv {
                    Value::DateTime(t) => *t,
                    Value::Empty => return Ok(false),
                    other => {
                        let s = other.to_str();
                        if s.is_empty() {
                            return Ok(false);
                        }
                        match datetime::parse_datetime(&s, self.env.us_dates) {
                            Ok((a, _)) => a,
                            Err(_) => return Ok(false),
                        }
                    }
                };
                Ok(match op {
                    Op::Eq | Op::Eeq => l >= start && l <= end,
                    Op::Ne | Op::Ene => !(l >= start && l <= end),
                    Op::Gt => l > end,
                    Op::Gte => l >= start,
                    Op::Lt => l < start,
                    Op::Lte => l <= end,
                    Op::Rx | Op::NotRx | Op::Like | Op::NotLike => {
                        let m = match op {
                            Op::Rx | Op::NotRx => self.get_regex(r)?.is_match(&lv.to_str()),
                            _ => self.get_regex(&util::like_to_regex(r))?.is_match(&lv.to_str()),
                        };
                        if matches!(op, Op::Rx | Op::Like) {
                            m
                        } else {
                            !m
                        }
                    }
                })
            }
        }
    }

    // ---------------------------------------------------------------- functions

    fn apply_function(&self, f: Function, args: &[Value], fi: Option<&FileInfo>) -> Result<Value, String> {
        crate::functions::apply(f, args, fi, self.config())
    }
}

fn query_is_correlated(q: &Query) -> bool {
    fn has_alias(e: &Expr) -> bool {
        match &e.kind {
            ExprKind::AliasField(..) => true,
            ExprKind::Function(_, args) => args.iter().any(has_alias),
            ExprKind::Arith(l, _, r) | ExprKind::Cmp(l, _, r) | ExprKind::And(l, r) | ExprKind::Or(l, r) => {
                has_alias(l) || has_alias(r)
            }
            ExprKind::Between(a, b, c, _) => has_alias(a) || has_alias(b) || has_alias(c),
            ExprKind::InList(a, l, _) => has_alias(a) || l.iter().any(has_alias),
            ExprKind::InQuery(a, q, _) => has_alias(a) || query_is_correlated(q),
            ExprKind::Exists(q, _) => query_is_correlated(q),
            ExprKind::Not(e) => has_alias(e),
            _ => false,
        }
    }
    q.fields.iter().any(has_alias) || q.expr.as_ref().map(has_alias).unwrap_or(false)
}

fn typed_sort_value(t: CmpType, v: Value) -> Value {
    match t {
        CmpType::Int => match v.to_i64_opt() {
            Some(i) => Value::Int(i),
            None => Value::Empty,
        },
        CmpType::Float => match v.to_f64_opt() {
            Some(f) => Value::Float(f),
            None => Value::Empty,
        },
        _ => v,
    }
}

fn compare_values(a: &Value, b: &Value) -> Ordering {
    match (a, b) {
        (Value::Empty, Value::Empty) => Ordering::Equal,
        (Value::Empty, _) => Ordering::Less,
        (_, Value::Empty) => Ordering::Greater,
        (Value::Int(x), Value::Int(y)) => x.cmp(y),
        (Value::Float(x), Value::Float(y)) => x.partial_cmp(y).unwrap_or(Ordering::Equal),
        (Value::Int(x), Value::Float(y)) => (*x as f64).partial_cmp(y).unwrap_or(Ordering::Equal),
        (Value::Float(x), Value::Int(y)) => x.partial_cmp(&(*y as f64)).unwrap_or(Ordering::Equal),
        (Value::DateTime(x), Value::DateTime(y)) => x.cmp(y),
        (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
        _ => a.to_str().cmp(&b.to_str()),
    }
}

fn compare_keys(a: &[Value], b: &[Value], asc: &[bool]) -> Ordering {
    for i in 0..a.len().min(b.len()) {
        let o = compare_values(&a[i], &b[i]);
        let o = if asc.get(i).copied().unwrap_or(true) { o } else { o.reverse() };
        if o != Ordering::Equal {
            return o;
        }
    }
    Ordering::Equal
}

pub fn arith(l: &Value, op: ArithOp, r: &Value) -> Result<Value, String> {
    let a = l.to_f64();
    let b = r.to_f64();
    let v = match op {
        ArithOp::Add => a + b,
        ArithOp::Subtract => a - b,
        ArithOp::Multiply => a * b,
        ArithOp::Divide => {
            if b == 0.0 {
                return Err("Division by zero".to_string());
            }
            a / b
        }
        ArithOp::Modulo => {
            if b == 0.0 {
                return Err("Division by zero".to_string());
            }
            a % b
        }
    };
    Ok(Value::Float(v))
}

fn aggregate_value(f: Function, rows: usize, vals: &[String]) -> Value {
    if f == Function::Count {
        return Value::Int(rows as i64);
    }
    let mut nums = vec![];
    for v in vals {
        if v.is_empty() {
            continue;
        }
        match util::str_to_f64_opt(v) {
            Some(x) => nums.push(x),
            None => return Value::Empty,
        }
    }
    if nums.is_empty() {
        return Value::Empty;
    }
    let n = nums.len() as f64;
    let sum: f64 = nums.iter().sum();
    let mean = sum / n;
    let var_sum = || nums.iter().map(|x| (x - mean) * (x - mean)).sum::<f64>();
    match f {
        Function::Sum => Value::Float(sum),
        Function::Avg => Value::Float(mean),
        Function::Min => Value::Float(nums.iter().cloned().fold(f64::INFINITY, f64::min)),
        Function::Max => Value::Float(nums.iter().cloned().fold(f64::NEG_INFINITY, f64::max)),
        Function::VarPop => Value::Float(var_sum() / n),
        Function::StdDevPop => Value::Float((var_sum() / n).sqrt()),
        Function::VarSamp => {
            if nums.len() < 2 {
                Value::Empty
            } else {
                Value::Float(var_sum() / (n - 1.0))
            }
        }
        Function::StdDevSamp => {
            if nums.len() < 2 {
                Value::Empty
            } else {
                Value::Float((var_sum() / (n - 1.0)).sqrt())
            }
        }
        _ => Value::Empty,
    }
}

