fn header(colors: bool) -> String {
    if colors {
        "fselect \x1b[33m0.10.0\x1b[0m\nFind files with SQL-like queries.\n\x1b[4;36mhttps://github.com/jhspetersson/fselect\x1b[0m\n".to_string()
    } else {
        "fselect 0.10.0\nFind files with SQL-like queries.\nhttps://github.com/jhspetersson/fselect\n".to_string()
    }
}

fn short_usage(colors: bool, full: bool) {
    let mut s = header(colors);
    s.push('\n');
    s.push_str(USAGE_LINE);
    s.push('\n');
    if full {
        s.push_str("\nFor more detailed instructions please refer to the URL above or run fselect --help\n");
    }
    let _ = std::io::stdout().write_all(s.as_bytes());
    let _ = std::io::stdout().flush();
}

fn help(colors: bool) {
    let mut text = HELP.to_string();
    if colors {
        text = text.replacen("fselect 0.10.0\n", "fselect \x1b[33m0.10.0\x1b[0m\n", 1);
        text = text.replacen(
            "\nhttps://github.com/jhspetersson/fselect\n",
            "\n\x1b[4;36mhttps://github.com/jhspetersson/fselect\x1b[0m\n",
