            "    \x1b[4;36mhttps://docs.rs/regex/1.10.2/regex/#syntax\x1b[0m\n",
            1,
        );
    }
    let _ = std::io::stdout().write_all(text.as_bytes());
    let _ = std::io::stdout().flush();
}

/// Parses and runs a query. Returns the exit code.
fn exec_query(env: &Env, args: &[String]) -> i32 {
    let raw = args.join(" ");
    let lexemes = lexer::Lexer::new(args).all();
    let mut p = parser::Parser::new(lexemes);
    let query = match p.parse(&raw) {
        Ok(q) => q,
        Err(e) => {
            env.error("query", &e);
            return 2;
        }
    };
    let mut s = Searcher::new(env, &query);
    if s.run() {
        1
    } else {
        0
    }
}

fn interactive(env: &Env, colors: bool) -> i32 {
    let stdin = std::io::stdin();
