//! Minimal EXIF reader (JPEG APP1 / TIFF / PNG eXIf / WebP EXIF).

use std::collections::HashMap;

#[derive(Clone, Debug)]
pub enum ExifValue {
    Byte(Vec<u8>),
    Ascii(Vec<Vec<u8>>),
    Short(Vec<u16>),
    Long(Vec<u32>),
    Rational(Vec<(u32, u32)>),
    SByte(Vec<i8>),
    Undefined(Vec<u8>),
    SShort(Vec<i16>),
    SLong(Vec<i32>),
    SRational(Vec<(i32, i32)>),
    Float(Vec<f32>),
    Double(Vec<f64>),
}

#[derive(Default, Clone, Debug)]
pub struct Exif {
    pub primary: HashMap<u16, ExifValue>,
    pub exif: HashMap<u16, ExifValue>,
    pub gps: HashMap<u16, ExifValue>,
}

fn find_tiff(data: &[u8]) -> Option<&[u8]> {
    if data.len() >= 4 && (&data[..4] == b"II*\x00" || &data[..4] == b"MM\x00*") {
        return Some(data);
    }
    if data.len() >= 2 && data[0] == 0xff && data[1] == 0xd8 {
        let mut i = 2;
        while i + 4 <= data.len() {
            if data[i] != 0xff {
                return None;
            }
            let marker = data[i + 1];
            if marker == 0xff {
                i += 1;
                continue;
            }
            if marker == 0xd8 || (0xd0..=0xd7).contains(&marker) || marker == 0x01 {
                i += 2;
                continue;
            }
            if marker == 0xd9 || marker == 0xda {
                return None;
            }
            let len = ((data[i + 2] as usize) << 8) | data[i + 3] as usize;
            if len < 2 || i + 2 + len > data.len() {
                return None;
            }
            let seg = &data[i + 4..i + 2 + len];
            if marker == 0xe1 && seg.len() >= 6 && &seg[..6] == b"Exif\x00\x00" {
                return Some(&seg[6..]);
            }
            i += 2 + len;
        }
        return None;
    }
    if data.len() >= 8 && &data[..8] == b"\x89PNG\r\n\x1a\n" {
        let mut i = 8;
        while i + 8 <= data.len() {
            let len = u32::from_be_bytes([data[i], data[i + 1], data[i + 2], data[i + 3]]) as usize;
            let typ = &data[i + 4..i + 8];
            if i + 8 + len > data.len() {
                return None;
            }
            if typ == b"eXIf" {
                return Some(&data[i + 8..i + 8 + len]);
            }
            if typ == b"IEND" {
                return None;
            }
            i += 12 + len;
        }
        return None;
    }
    if data.len() >= 12 && &data[..4] == b"RIFF" && &data[8..12] == b"WEBP" {
        let mut i = 12;
        while i + 8 <= data.len() {
            let len = u32::from_le_bytes([data[i + 4], data[i + 5], data[i + 6], data[i + 7]]) as usize;
            if i + 8 + len > data.len() {
                return None;
            }
            if &data[i..i + 4] == b"EXIF" {
                let c = &data[i + 8..i + 8 + len];
                if c.len() >= 6 && &c[..6] == b"Exif\x00\x00" {
                    return Some(&c[6..]);
                }
                return Some(c);
            }
            i += 8 + len + (len & 1);
        }
    }
    None
}

struct Reader<'a> {
    d: &'a [u8],
    le: bool,
}

impl<'a> Reader<'a> {
    fn u16(&self, o: usize) -> Option<u16> {
        let b = self.d.get(o..o + 2)?;
        Some(if self.le { u16::from_le_bytes([b[0], b[1]]) } else { u16::from_be_bytes([b[0], b[1]]) })
    }
    fn u32(&self, o: usize) -> Option<u32> {
        let b = self.d.get(o..o + 4)?;
        Some(if self.le {
            u32::from_le_bytes([b[0], b[1], b[2], b[3]])
        } else {
            u32::from_be_bytes([b[0], b[1], b[2], b[3]])
        })
    }

    fn value(&self, typ: u16, count: usize, off: usize) -> Option<ExifValue> {
        let unit = match typ {
            1 | 2 | 6 | 7 => 1,
            3 | 8 => 2,
            4 | 9 | 11 => 4,
            5 | 10 | 12 => 8,
            _ => return None,
        };
        let total = unit * count;
        let start = if total <= 4 { off } else { self.u32(off)? as usize };
        let bytes = self.d.get(start..start + total)?;
        Some(match typ {
            1 => ExifValue::Byte(bytes.to_vec()),
            2 => ExifValue::Ascii(
                {
                    let mut v: Vec<Vec<u8>> = bytes.split(|&b| b == 0).map(|s| s.to_vec()).collect();
                    if bytes.last() == Some(&0) {
                        v.pop();
                    }
                    v
                },
            ),
            3 => ExifValue::Short((0..count).map(|i| self.u16(start + i * 2).unwrap_or(0)).collect()),
            4 => ExifValue::Long((0..count).map(|i| self.u32(start + i * 4).unwrap_or(0)).collect()),
            5 => ExifValue::Rational(
                (0..count)
                    .map(|i| (self.u32(start + i * 8).unwrap_or(0), self.u32(start + i * 8 + 4).unwrap_or(0)))
                    .collect(),
            ),
            6 => ExifValue::SByte(bytes.iter().map(|&b| b as i8).collect()),
            7 => ExifValue::Undefined(bytes.to_vec()),
            8 => ExifValue::SShort((0..count).map(|i| self.u16(start + i * 2).unwrap_or(0) as i16).collect()),
            9 => ExifValue::SLong((0..count).map(|i| self.u32(start + i * 4).unwrap_or(0) as i32).collect()),
            10 => ExifValue::SRational(
                (0..count)
                    .map(|i| {
                        (self.u32(start + i * 8).unwrap_or(0) as i32, self.u32(start + i * 8 + 4).unwrap_or(0) as i32)
                    })
                    .collect(),
            ),
            11 => ExifValue::Float((0..count).map(|i| f32::from_bits(self.u32(start + i * 4).unwrap_or(0))).collect()),
            12 => ExifValue::Double(
                (0..count)
                    .map(|i| {
                        let a = self.u32(start + i * 8).unwrap_or(0) as u64;
                        let b = self.u32(start + i * 8 + 4).unwrap_or(0) as u64;
                        f64::from_bits(if self.le { a | (b << 32) } else { (a << 32) | b })
                    })
                    .collect(),
            ),
            _ => return None,
        })
    }

    fn ifd(&self, off: usize) -> Option<(HashMap<u16, ExifValue>, u32)> {
        let n = self.u16(off)? as usize;
        let mut m = HashMap::new();
        for k in 0..n {
            let e = off + 2 + k * 12;
            let tag = self.u16(e)?;
            let typ = self.u16(e + 2)?;
            let count = self.u32(e + 4)? as usize;
            if count > 1_000_000 {
                continue;
            }
            if let Some(v) = self.value(typ, count, e + 8) {
                m.insert(tag, v);
            }
        }
        let next = self.u32(off + 2 + n * 12).unwrap_or(0);
        Some((m, next))
    }
}

fn first_u32(v: &ExifValue) -> Option<u32> {
    match v {
        ExifValue::Long(l) => l.first().copied(),
        ExifValue::Short(s) => s.first().map(|x| *x as u32),
        _ => None,
    }
}

pub fn parse(data: &[u8]) -> Option<Exif> {
    let t = find_tiff(data)?;
    if t.len() < 8 {
        return None;
    }
    let le = match &t[..2] {
        b"II" => true,
        b"MM" => false,
        _ => return None,
    };
    let r = Reader { d: t, le };
    if r.u16(2)? != 42 {
        return None;
    }
    let off = r.u32(4)? as usize;
    let (primary, _) = r.ifd(off)?;
    let mut ex = Exif { primary, ..Default::default() };
    if let Some(p) = ex.primary.get(&0x8769).and_then(first_u32) {
        if let Some((m, _)) = r.ifd(p as usize) {
            ex.exif = m;
        }
    }
    if let Some(p) = ex.primary.get(&0x8825).and_then(first_u32) {
        if let Some((m, _)) = r.ifd(p as usize) {
            ex.gps = m;
        }
    }
    Some(ex)
}

fn ascii(v: &ExifValue) -> Option<String> {
    match v {
        ExifValue::Ascii(parts) => {
            let p = parts.first()?;
            if p.is_empty() {
                return None;
            }
            Some(String::from_utf8_lossy(p).to_string())
        }
        _ => None,
    }
}

fn rational_f64(v: &ExifValue) -> Option<f64> {
    match v {
        ExifValue::Rational(r) => r.first().map(|(n, d)| *n as f64 / *d as f64),
        ExifValue::SRational(r) => r.first().map(|(n, d)| *n as f64 / *d as f64),
        _ => None,
    }
}

fn uint_list(v: &ExifValue) -> Option<Vec<u64>> {
    match v {
        ExifValue::Short(s) => Some(s.iter().map(|x| *x as u64).collect()),
        ExifValue::Long(s) => Some(s.iter().map(|x| *x as u64).collect()),
        ExifValue::Byte(s) => Some(s.iter().map(|x| *x as u64).collect()),
        _ => None,
    }
}

fn first_uint(v: &ExifValue) -> Option<u64> {
    uint_list(v).and_then(|l| l.first().copied())
}

fn hex(b: &[u8]) -> String {
    let mut s = String::from("0x");
    for x in b {
        s.push_str(&format!("{:02x}", x));
    }
    s
}

fn parse_exif_datetime(s: &str) -> Option<(i32, u32, u32, u32, u32, u32)> {
    let b = s.as_bytes();
    if b.len() < 16 {
        return None;
    }
    let num = |a: usize, n: usize| -> Option<u32> {
        let p = s.get(a..a + n)?;
        if p.chars().all(|c| c.is_ascii_digit()) {
            p.parse().ok()
        } else {
            None
        }
    };
    let y = num(0, 4)? as i32;
    if !(b[4] == b':' || b[4] == b'-') || !(b[7] == b':' || b[7] == b'-') || b[10] != b' ' || b[13] != b':' {
        return None;
    }
    let mo = num(5, 2)?;
    let d = num(8, 2)?;
    let h = num(11, 2)?;
    let mi = num(14, 2)?;
    let sec = if b.len() >= 19 && b[16] == b':' { num(17, 2)? } else { 0 };
    Some((y, mo, d, h, mi, sec))
}

pub fn datetime(ex: &Exif, tag: u16) -> Option<(i32, u32, u32, u32, u32, u32)> {
    let v = if tag == 0x0132 { ex.primary.get(&tag) } else { ex.exif.get(&tag) }?;
    let s = ascii(v)?;
    parse_exif_datetime(&s)
}

fn reserved(name: &str, v: u64) -> String {
    format!("[reserved {} {}]", name, v)
}

fn gps_coord(ex: &Exif, val_tag: u16, ref_tag: u16) -> Option<f32> {
    let r = ascii(ex.gps.get(&ref_tag)?)?;
    let v = match ex.gps.get(&val_tag)? {
        ExifValue::Rational(r) => r.clone(),
        _ => return None,
    };
    if v.len() < 3 {
        return None;
    }
    let f = |x: (u32, u32)| x.0 as f32 / x.1 as f32;
    let mut val = f(v[0]) + f(v[1]) / 60.0 + f(v[2]) / 3600.0;
    if r == "S" || r == "W" {
        val = -val;
    }
    Some(val)
}

pub fn gps_latitude(ex: &Exif) -> Option<f32> {
    gps_coord(ex, 0x0002, 0x0001)
}

pub fn gps_longitude(ex: &Exif) -> Option<f32> {
    gps_coord(ex, 0x0004, 0x0003)
}

pub fn gps_altitude(ex: &Exif) -> Option<f32> {
    ex.gps.get(&0x0005)?;
    match ex.gps.get(&0x0006)? {
        ExifValue::Rational(r) => r.first().map(|(n, d)| *n as f32 / *d as f32),
        _ => None,
    }
}

/// Returns the display string of a tag (mostly following common EXIF conventions).
pub fn display(ex: &Exif, key: &str) -> Option<String> {
    let p = |t: u16| ex.primary.get(&t);
    let e = |t: u16| ex.exif.get(&t);
    match key {
        "make" => ascii(p(0x010f)?),
        "model" => ascii(p(0x0110)?),
        "software" => ascii(p(0x0131)?),
        "description" => ascii(p(0x010e)?),
        "artist" => ascii(p(0x013b)?),
        "copyright" => ascii(p(0x8298)?),
        "lens_make" => ascii(e(0xa433)?),
        "lens_model" => ascii(e(0xa434)?),
        "body_serial" => ascii(e(0xa431)?),
        "lens_serial" => ascii(e(0xa435)?),
        "version" => match e(0x9000)? {
            ExifValue::Undefined(u) => {
                if u.len() == 4 && u.iter().all(|c| c.is_ascii_digit()) {
                    let major: u32 = std::str::from_utf8(&u[0..2]).ok()?.parse().ok()?;
                    let minor: u32 = std::str::from_utf8(&u[2..4]).ok()?.parse().ok()?;
                    if minor % 10 == 0 {
                        Some(format!("{}.{}", major, minor / 10))
                    } else {
                        Some(format!("{}.{:02}", major, minor))
                    }
                } else {
                    Some(hex(u))
                }
            }
            _ => None,
        },
        "exposure_time" => match e(0x829a)? {
            ExifValue::Rational(r) => {
                let (n, d) = *r.first()?;
                if n >= d {
                    Some(format!("{}", n as f64 / d as f64))
                } else if n != 0 {
                    Some(format!("1/{}", d as f64 / n as f64))
                } else {
                    Some(format!("{}/{}", n, d))
                }
            }
            _ => None,
        },
        "aperture" => rational_f64(e(0x9202)?).map(|f| format!("{}", f)),
        "shutter_speed" => rational_f64(e(0x9201)?).map(|f| format!("{}", f)),
        "f_number" => rational_f64(e(0x829d)?).map(|f| format!("{}", f)),
        "focal_length" => rational_f64(e(0x920a)?).map(|f| format!("{}", f)),
        "exposure_bias" => rational_f64(e(0x9204)?).map(|f| format!("{}", f)),
        "max_aperture" => rational_f64(e(0xa405).or(e(0x9205))?).map(|f| format!("{}", f)),
        "digital_zoom" => {
            let f = rational_f64(e(0xa404)?)?;
            if f == 0.0 {
                Some("unused".to_string())
            } else {
                Some(format!("{}", f))
            }
        }
        "iso_speed" => uint_list(e(0x8833)?).map(join_nums),
        "sensitivity" => uint_list(e(0x8827)?).map(join_nums),
        "image_width" => uint_list(e(0xa002)?).map(join_nums),
        "image_height" => uint_list(e(0xa003)?).map(join_nums),
        "user_comment" => match e(0x9286)? {
            ExifValue::Undefined(u) => Some(hex(u)),
            _ => None,
        },
        "orientation" => {
            let v = first_uint(p(0x0112)?)?;
            Some(match v {
                1 => "row 0 at top and column 0 at left".to_string(),
                2 => "row 0 at top and column 0 at right".to_string(),
                3 => "row 0 at bottom and column 0 at right".to_string(),
                4 => "row 0 at bottom and column 0 at left".to_string(),
                5 => "row 0 at left and column 0 at top".to_string(),
                6 => "row 0 at right and column 0 at top".to_string(),
                7 => "row 0 at right and column 0 at bottom".to_string(),
                8 => "row 0 at left and column 0 at bottom".to_string(),
                _ => reserved("orientation", v),
            })
        }
        "flash" => {
