    for c in t.bytes() {
        let v = B64.iter().position(|&x| x == c)? as u32;
        vals.push(v);
    }
    if vals.len() % 4 == 1 {
        return None;
    }
    let mut out = vec![];
    for chunk in vals.chunks(4) {
        let mut n: u32 = 0;
        for (i, v) in chunk.iter().enumerate() {
            n |= v << (18 - 6 * i as u32);
        }
        out.push((n >> 16) as u8);
        if chunk.len() > 2 {
            out.push((n >> 8) as u8);
        }
        if chunk.len() > 3 {
            out.push(n as u8);
        }
    }
    Some(out)
}

